        "explanation": "주식의 이익평가모형 관련하여 PEGR(Price Earning Growth Ratio) 이란 PER의 내용을\n한 차원 높게 해석한 이익평가모형이다.\nPER은 다분히 과거지향적인 자료(과거의 당기순이익)에 기인한다. 그러나 미래지향적으로\n그 기업의 향후 성장성에 비해서 주가가 높게 혹은 낮게 평가되었는지를 판단할 필요가 있\n다.\nPEGR은 특정 주식의 PER을 당해 기업 주당 순이익(PER)의 성장률(growth)로 나누어준\n수치로서 PEGR이 낮다면 향후 주가상승으로 이어질 가능성이 높다고 해석할 수 있다.\n※ PEGR 공식 = PER/연평균EPS성장률,\nEPS= Earning Per Share.",
