        "explanation": "유성형(shooting star)은 한 개의 캔들차트로서 상승추세가 한계에 다다라 추세의 하락반\n전을 예고하는 신호이다. 유성형은 대개 갭(gap)을 동반하여 작은 몸체와 위로 몸체보다\n2배 이상 되는 긴 꼬리를 갖춘 캔들차트의 모습을 하는데 양선 보다 음선의 신뢰도가 높\n다.\n까마귀형(up side gap two Crows)은 천장권에서 나타나는 하락전환 신호이다. 우선 상승\n추세에서 긴 양선이 출현한 후 둘째날 갭(gap)이 발생하면서 음선이 나오고, 연이어 셋째\n날 음선이 출현하면서 갭을 메꾸게 되는 것이다.\n(※ 3마리(캔들이 3개 이상)의 까마귀가 전선줄에 걸터앉아서 기분나쁘게 내려다보는(하락\n형) 형상이다)",
