        "answerNote": null,
        "explanation": "OBV(On Balance Volume)선은 거래량 지표로서, 거래량은 주가에 선행한다는 전제하에\n주가가 전일에 비하여 상승한 날의 거래량 누계에서 하락한 날의 누계를 차감하여 이를\n매일 누적적으로 집계하여 도표화한 것이다. (출제가 빈번하다)\n-> 스토캐스틱은 지표분석으로서 현재 주가가 일정기간 동안 상승과 하락 범위 내에서 어\n느 정도에 위치하는지를 나타내는 지표이며, 현재 주가가 일정기간 동안 상승과 하락한 범\n위 내에서 최고가라면 100%이고, 만약 최저가라면 0%로 나타낸다. 일반적으로 스토캐스\n틱 수치가 85% 이상일 경우에는 과매수 구간이며 15% 미만이라면 과매도 구간이라고 한\n다.\n-볼린저 밴드는 주가의 변동을 분석하기 위해, 중심이 되는 이동평균선을 기준으로 일정\n한 표준편차 범위만큼 설정한 그래프를 말한다. 가격의 추세를 포착할 수 있도록 설정된\n중간선(중단 밴드)과 가격의 상대적 높낮음에 대한 판단 기준이 되는 두 개의 밴드(상단,하\n단)로 구성되어 있다.\n볼린저 밴드에서 상단 밴드와 하단 밴드는 중단 밴드에서 2 표준편차만큼 더하거나 뺀 값\n이다. 주가가 정규분포를 따른다고 가정한다면, 상단 밴드와 하단 밴드를 벗어날 확률은\n각각 2.25%에 불과하며, 밴드 내부에 머무를 확률은 대략 95%에 달한다.\n따라서 주가가 상단 밴드나 하단 밴드에 근접한다면 시장이 과매수 국면이거나 과매도 국\n면에 달했을 가능성이 있으며, 각 밴드가 저항선 혹은 지지선으로 작용할 것으로 기대할\n수 있다.",
