        "explanation": "불성실공시란 상장법인이 자본시장법 및 유가증권시장 공시규정에 의한 공시의무를 성실히\n이행하지 아니하여 공시불이행, 공시번복 또는 공시변경에 해당하는 위반행위를 하는 것을\n말한다. 불성실공시법인지정은 자본시장법 상의 허위공시 등에 대한 제재나 금융위의 공시\n의무위반에 대한 제재 외에 자율규제기관인 거래소의 제재조치로서 상장법인의 성실한 공\n시의무이행을 위해 시행하고 있는 제도라고 할 수 있다.\n불성실공시의 유형에는 공시불이행,공시번복, 공시변경의 3가지가 있다.\n(공시의 종류에는 자율공시, 조회공시, 공정공시가 있다)\n※다음 사항에 해당하게 될 경우 불성실공시법인으로 지정한다.\n1) 공시불이행\n-주요경영사항 등을 공시기한 이내에 신고하지 아니한 때\n- 주요경영사항 등을 거짓으로 또는 잘못 공시하거나 중요사항을 기재하지 아니하고 공시한\n경우\n-확인절차 면제 공시에 대한 거래소의 정정요구에도 불구하고 정정시한까지 공시내용을 정\n정하여 공시하지 아니한 경우\n2) 공시번복\n- 이미 신고•공시한 내용에 대한 전면취소, 부인 또는 이에 준하는 내용을 공시한 때\n3) 공시변경\n-기공시한 사항중 중요한 부분에 대해 변경이 발생한 경우",
