        "explanation": "역나비형 투자전략은 적극적 투자전략으로서, 현재 평평한 형태를 띄고 있는 수익률곡선\n이 향후 중기물의 수익률은 하락하고 단기물과 장기물의 수익률은 상대적으로 상승함으로\n써 수익률 곡선의 형태가 역나비형 형태를 띌 것으로 *예측할 때* 취하는 전략이다. 따라\n서 포트폴리오에서 장•단기물의 비중을 줄이고 중기물을 매입함으로써 중기물의 비중을\n확대시키는 방식을 취한다.\n채권의 소극적 투자전략에는 만기보유전략,인덱스전략, 현금흐름일치전략, 사다리형 만기\n운용전략, 바벨(아령)형 만기운용전략, 면역전략이 있다.\n이 중 면역전략은 채권을 매입 후 만기까지 보유하면 매입 시의 만기수익률(YTM)이 실\n현되는 만기 일시상환채권을 채권의 잔존기간과 투자기간을 일치시킴으로써 목표투자를 달\n성할 수 있을 뿐만 아니라 수익률 변동에 의한 가격변동 위험도 피할 수 있다. 그러나 이\n표채와 같이 투자기간 동안의 현금흐름이 여러 번 발생하는 채권에 투자해야만 하는 경우\n에는 채권의 잔존만기와 투자기간을 일치시키더라도 수익률 변동의 위험을 완전히 제거할\n수 없다.",
