        "explanation": "코넥스시장은 비상장기업중 중소기업만 상장이 가능하다. 코넥스는 자본시장을 통한 초기\n중소 • 벤처기업의 성장지원 및 모험자본 선순환 체계 구축을 위해 개설된 초기 • 중소기업\n전용 신시장이다.\n• 코넥스(KONEX, Korea New Exchange)시장의 개설배경\n현재 중소기업의 자금조달 현황을 살펴보면 대부분 은행대출에 편중되어 있고, 직접금융\n(주식발행)을 통한 자금조달은 매우 낮은 수준이다. 이로 인해 중소기업 등 비상장기업의\n부채비율이 높아지고, 이자비용 부담도 상장기업에 비해 과중한 실정이며 은행의 대출정책\n변화 등에 따라 기업의 존립이 위협받을 수 있는 가능성도 있다. 중소기업 자금조달이 이\n처럼 은행대출 등에 편중된 배경에는 코스닥시장만을 통해 초기 중소•벤처기업을 지원하는\n것이 현실적으로는 한계가 있었던 점도 작용하였다.\n코스닥시장의 경우 투자자 보호를 위한 계속적인 상장요건 강화로 인해 성숙단계의 중소\n기업 대상 시장으로 변모하여 초기 중소기업은 진입이 곤란한 시장이 되었으며, 설립부터\n코스닥시장 상장까지 소요되는 기간이 2004년에는 평균 9.3년이었던 것에 비해, 2011년도\n에는 평균 13.3년으로 크게 늘어났다.\n이러한 이유로 초기 중소기업에 최적화된 증권시장의 필요성이 제기되었으며, 초기 중소\n기업 특성을 반영한 시장제도를 마련하기 위해서는 기존 증권시장을 활용하기 보다는 제로\n베이스에서 설계하는 것이 용이하다는 판단 하에 코넥스시장을 개설하게 되었다.",
