        "answerNote": null,
        "explanation": "K- OTC는 단일의 매도자와 매수자간에 매매하는 상대매매방식이다. K- OTC는 경쟁매매,\n시간외매매제도, 신용거래등의 시장제도가 없으나 그 밖에 매매거래를 위한 계좌의 개설,\n주문제출, 결제,호가 및 시세공표 등의 시장제도는 거래소 시장과 유사하다\nK-OTC 등록 또는 지정해제 사유\n1. 발행한 어음 또는 수표가 거래은행에 의하여 최종부도로 결정되거나 거래은행과의 거래\n가 정지된 경우\n2. 최근 사업연도말을 기준으로 자본전액식 상태인 경우. 다만, 결산기 정기공시서류의\n제출기한까지 협회장이 정하는 바에 따라 자본전액잠식 상태를 해소하였음이 확인된 경우\n는 제외\n3. 최근 사업연도 매출액이 1억원 미만이거나 최근 2개 사업연도에 연속하여 매출액이 5\n억원(크라우드펀딩 특례 적용 기업의 경우 3억원) 미만인 경우\n4. 최근 사업연도의 재무제표에 대한 감사인의 감사의견이 부적정, 의견거절이거나 최근 2\n개 사업연도에 연속하여 감사범위제한으로 인한 한정인 경우\n5. 주된 영업이 6개월 이상 정지되어 잔여사업 부문만으로는 실질적인 영업을 영위하기 어\n렵거나 영업의 전부가 양도되는 경우.\n6. 「채무자 회생 및 파산에 관한 법률』에 따른 법원의 회생절차개시신청 기각, 회생절차개\n시결정 취소, 회생계획인가 및 회생절차폐지 결정이 있는 경우. 다만, 「채무자 회생 및\n파산에 관한 법률』 제287조에 따른 회생절차폐지의 경우에는 적용하지 않음\n7. 정기공시서류 제출과 관련하여 다음 각 목의 어느 하나에 해당하는 경우\n가. 결산기 정기공시서류를 제출기한까지 제출하지 아니한 후 제출기한의 다음 날부터 30\n일 이내에 제출 하지 아니한 경우\n나. 반기 정기공시서류를 최근 4개 사업연도에 1회 이상 제출기한까지 제출하지 아니한 법\n인이 최근 반기에 반기 정기공시서류를 제출기한까지 제출하지 아니한 후 제출기한의 다음\n날부터 15일 이내에 제출하지 아니한 경우\n8. 증권시장에 상장되는 경우",
