        "explanation": "법인 기타 단체의 고유재산관리업무를 수행하는 직원에게 (사용범위가 한정된) 문화상품권\n을 (연극 및 스포츠, 음악회 등)제공하는 경우는 제외된다.\n※영업 및 업무에 관한 규정, 제2-68조(부당한 재산상 이익의 제공 및 수령금지)\n① 금융투자회사는 다음 각 호의 어느 하나에 해당하는 경우 재산상 이익을 제공하거나 제\n공받아서는 아니 된다.\n1. 경제적 가치의 크기가 일반인이 통상적으로 이해하는 수준을 초과하는 경우\n2. 재산상 이익의 내용이 사회적 상규에 반하거나 거래상대방의 공정한 업무수행을 저해하\n는 경우\n3. 재산상 이익의 제공 또는 수령이 비정상적인 조건의 금융투자상품 매매거래. 투자자문\n계약, 투자일임계약 또는 신탁계약의 체결 등의 방법으로 이루어지는 경우\n4. 다음 각 목의 어느 하나에 해당하는 경우로서 거래상대방에게 금전, 상품권, 금융투자\n상품을 제공하는 경우. 다만, 사용범위가 공연 • 운동경기 관람, 도서 • 음반 구입 등 문화활\n동으로 한정된 상품권을 제공하는 경우는 제외한다.\n가. 집합투자회사, 투자일임회사 또는 신탁회사 등 타인의 재산을 일임받아 이를 금융투자\n회사가 취급하는 금융투자상품 등에 운용하는 것을 업무로 영위하는 자(그 임원 및 재산의\n운용에 관하여 의사결정을 하는 자를 포함)에게 제공하는 경우\n나. 법인 기타 단체의 고유재산관리업무를 수행하는 자에게 제공하는 경우\n다. 집합투자회사가 자신이 운용하는 집합투자기구의 집합투자증권을 판매하는 투자매매회\n사(투자매매업을 영위하는 금융투자회사), 투자중개회사(투자중개업을 영위하는 금융투자회\n사) 및 그 임직원과 투자권유대행인에게 제공하는 경우\n5. 재산상 이익의 제공 또는 수령이 위법 • 부당행위의 은닉 또는 그 대가를 목적으로 하는\n경우\n6. 거래상대방만 참석한 여가 및 오락활동 등에 수반되는 비용을 제공하는 경우\n7. 금융투자상품 및 경제정보 등과 관련된 전산기기의 구입이나 통신서비스 이용에 소요되\n는 비용을 제공하거나 제공받는 경우. 다만, 제2-63조제2항제1호에 해당하는 경우(금융\n투자상품에 대한 가치분석•매매정보 또는 주문의 집행 등을 위하여 자체적으로 개발한 소\n프트웨어 및 해당 소프트웨어의 활용에 불가피한 컴퓨터 등 전산기기를 제공하는 경우)는\n제외한다.\n8. 집합투자회사가 자신이 운용하는 집합투자기구의 집합투자증권의 판매실적에 연동하여\n이를 판매하는 투자매매회사 • 투자중개회사(그 임직원 및 투자권유대행인을 포함한다)에게\n재산상 이익을 제공하는 경우\n9. 투자매매회사 또는 투자중개회사가 판매회사의 변경 또는 변경에 따른 이동액을 조건으\n로 하여 재산상 이익을 제공하는 경우",
        "sourceText": "54. 다음 중 ‘금융투자회사의 영업 및 업무에 관한 규정’에서 정하고 있는 부당한 재산상 이익\n의 제공에 해당되지 않는 것은? (★★☆)\n① 거래상대방만 참석한 여가 및 오락활동 등에 수반되는 비용을 제공하는 경우\n② IT스타트업 업체의 고유재산관리업무를 수행하는 직원에게 스포츠관람권을 제공하는 경\n우\n③ 집합투자업자가 자사펀드의 판매증권사 직원에게 백화점상품권을 제공하는 경우\n④ 증권회사 직원이 투자자에게 펀드 판매회사의 변경에 따른 이동액을 조건으로 재산상의\n이익을 제공하는 경우",
