        "answerNote": null,
        "explanation": "모두 옳다.\n※금융사지배구조법 제25조(준법감시인의 임면 등)\n1 금융회사(자산규모 등을 고려하여 대통령령으로 정하는 투자자문업자 및 투자\n일임업자는 제외한다)는 내부통제기준의 준수 여부를 점검하고 내부통제기준을 위\n반하는 경우 이를 조사하는 등 내부통제 관련 업무를 총괄하는 사람(준법감시인)\n을 1명 이상 두어야 하며, 준법감시인은 필요하다고 판단하는 경우 조사결과를 감\n사위원회 또는 감사에게 보고할 수 있다.\n금융회사는 사내이사 또는 업무집행책임자 중에서 준법감시인을 선임하여야 한\n다. 다만, 자산규모, 영위하는 금융업무 등을 고려하여 대통령령으로 정하는 금융\n회사 또는 외국금융회사의 국내지점은 사내이사 또는 업무집행책임자가 아닌 직원\n중에서 준법감시인을 선임할 수 있다.\n③ 금융회사(외국금융회사의 국내지점은 제외한다)가 준법감시인을 임면하려는 경\n우에는 이사회의 의결을 거쳐야 하며, 해임할 경우에는 이사 총수의 3분의 2 이상\n의 찬성으로 의결한다.\n④ 준법감시인의 임기는 2년 이상으로 한다.\n⑤ 금융회사는 준법감시인을 제2항 단서에 따라 직원 중에서 선임하는 경우 「기간\n제 및 단시간근로자 보호 등에 관한 법률」에 따른 기간제근로자 또는 단시간근로\n자를 준법감시인으로 선임하여서는 아니 된다.\n⑥ 금융회사는 준법감시인에 대하여 회사의 재무적 경영성과와 연동하지 아니하는\n별도의 보수지급 및 평가 기준을 마련하여 운영하여야 한다.\n(시행령)제25조(준법감시인 및 위험관리책임자의 임면에 따른 보고)\n① 금융회사는 준법감시인 또는 위험관리책임자를 임면하였을 때에는 그 사실을\n금융위원회에 임면일부터 7영업일 이내에 보고하여야 한다.",
