        "correctAnswer": 2,
        "answerNote": null,
        "explanation": "공개매수는 의결권이 있는 주식 등을 전제로 하므로 의결권이 없는 주식에 대해서는 의무\n공개매수 규정이 적용되지 않는다.\n적용대상증권에 전환사채권과 교환사채권도 포함되고, 공개매수 해당여부 판단시 본인과\n특별관계자의 지\n분을 합산하며, 특별관계자란 특수관계인과 공동보유자를 말한다. 원칙적으로 공개매수공\n고일 이후 공개매수철회는 금지된다.\n※자본시장법 제133조(공개매수의 적용대상)\n1 \"공개매수\"란 불특정 다수인에 대하여 의결권 있는 주식등의 매수(다른 증권과\n의 교환을 포함)의 청약을 하거나 매도(다른 증권과의 교환을 포함)의 청약을 권유\n하고 증권시장 및 다자간매매체결회사(이와 유사한 시장으로서 해외에 있는 시장\n을 포함) 밖에서 그 주식등을 매수하는 것을 말한다.\n③ 주식등을 6개월 동안 증권시장 밖에서 10인 이상의 자로부터 매수등을 하고자\n하는 자는 그 매수등을 한 후에 본인과 그 특별관계자가 보유하게 되는 주식등의\n수의 합계가 그 주식등의 총수의 100분의 5 이상이 되는 경우에는 공개매수를 하\n여야 한다. 다만, 매수등의 목적, 유형, 그 밖에 다른 주주의 권익침해 가능성 등\n을 고려하여 대통령령으로 정하는 매수등(->예를 들어,소각을 목적으로 하는 주식\n등의 매수인 경우 등)의 경우에는 공개매수 외의 방법으로 매수등을 할 수 있다.",
