        "correctAnswer": 3,
        "answerNote": null,
        "explanation": "상장사의 횡령 및 배임은 상장적격성 심사대상 등에 해당하며 금융위의 직접적인 조사대상\n은 아니다.\n※조사의 주요대상\n1) 미공개정보 이용행위\n2) 시세조종 등 불공정행위\n3) 내부자의 단기매매차익 취득\n4) 상장법인의 공시의무 위반\n5) 상장법인 임원등의 특정증권 및 변동상황 보고의무 위반 등\n6) 주식의 대량보유등의 보고(5% Rule)\n※자본시장조사 업무규정 제6조(조사의 실시 등)\n① 금융위는 다음 각 호의 어느 하나에 해당하는 경우에는 조사를 실시할 수 있다.\n1. 금융위 및 금융감독원의 업무와 관련하여 위법행위의 혐의사실을 발견한 경우\n2. 한국거래소로부터 위법행위의 혐의사실을 이첩받은 경우\n3. 각급 검찰청의 장으로부터 위법행위에 대한 조사를 요청받거나 그 밖의 행정기관으로\n부터 위법행위의 혐의사실을 통보받은 경우\n4. 위법행위에 관한 제보를 받거나 조사를 의뢰하는 민원을 접수한 경우\n5. 기타 공익 또는 투자자보호를 위하여 조사의 필요성이 있다고 인정하는 경우\n② 제1항의 규정에 불구하고 다음 각 호의 1에 해당하는 경우에는 조사를 실시하지 아니\n할 수 있다.\n1. 당해 위법행위에 대한 충분한 증거가 확보되어 있고 다른 위법행위의 혐의가 발견되지\n않는 경우\n2. 당해 위법행위와 함께 다른 위법행위의 혐의가 있으나 그 혐의내용이 경미하여 조사의\n실익이 없다고 판단되는 경우\n3. 공시자료, 언론보도 등에 의하여 널리 알려진 사실이나 풍문만을 근거로 조사를 의뢰하\n는 경우\n4. 민원인의 사적인 이해관계에서 당해 민원이 제기된 것으로 판단되는 등 공익 및 투자자\n보호와 직접적인 관련성이 적은 경우\n5. 당해 위법행위에 대한 제보가 익명 또는 가공인 명의의 진정 · 탄원• 투서 등에 의해 이\n루어지거나 그 내용이 조사단서로서의 가치가 없다고 판단되는 경우\n6. 당해 위법행위와 동일한 사안에 대하여 검찰이 수사를 개시한 사실이 확인된 경우",
