        "difficulty": 2,
        "question": "금융소비자보호법에서 정하고 있는 금융투자회사의 부당권유금지와 관련한 내용으로 옳지 않은 것은?",
        "options": [
          "보호받을 수 있는 대상은 일반금융소비자와 전문금융소비자에게 해당한다,",
          "장외파생상품을 방문판매하기 위하여 전문금융소비자에게는 사전연락을 할 수 있다.",
          "적합성의 원칙을 적용받지 아니하고 권유하기 위해 일반금융소비자로부터 계약체결의 권유를 원하지 않는다는 의사를 서면 등으로 받는 행위를 하여서는 아니된다.",
          "투자성 상품에 관한 계약체결을 권유하면서 일반금융소비자가 요청하지 않은 다른 대출 성상품을 안내하거나 관련정보를 제공해서는 안된다."
        ],
        "correctAnswer": 2,
        "answerNote": null,
        "explanation": "일반금융소비자와 전문금융소비자에게는 장외파생상품의 방문판매를 위한 사전연락을 금융\n상품판매업자 등이 먼저 할 수 없다.\n부당권유행위의 금지는 전문금융소비자와 일반금융소비자 모두에게 적용된다.\n※금소법 제21조(부당권유행위 금지)\n금융상품판매업자등은 계약 체결을 권유(금융상품자문업자가 자문에 응하는 것을 포\n함)하는 경우에 다음 각 호의 어느 하나에 해당하는 행위를 해서는 아니 된다. 다만,\n금융소비자 보호 및 건전한 거래질서를 해칠 우려가 없는 행위로서 대통령령으로 정\n하는 행위는 제외한다.\n1. 불확실한 사항에 대하여 단정적 판단을 제공하거나 확실하다고 오인하게 할 소지가\n있는 내용을 알리는 행위\n2. 금융상품의 내용을 사실과 다르게 알리는 행위\n3. 금융상품의 가치에 중대한 영향을 미치는 사항을 미리 알고 있으면서 금융소비자에\n게 알리지 아니하는 행위\n4. 금융상품 내용의 일부에 대하여 비교대상 및 기준을 밝히지 아니하거나 객관적인\n근거 없이 다른 금융상품과 비교하여 해당 금융상품이 우수하거나 유리하다고 알리는\n행위\n5. 보장성 상품의 경우 다음 각 목의 어느 하나에 해당하는 행위\n가. 금융소비자가 보장성 상품 계약의 중요한 사항을 금융상품직접판매업자에게 알리\n는 것을 방해하거나 알리지 아니할 것을 권유하는 행위\n나. 금융소비자가 보장성 상품 계약의 중요한 사항에 대하여 부실하게 금융상품직접판\n매업자에게 알릴 것을 권유하는 행위\n6. 투자성 상품의 경우 다음 각 목의 어느 하나에 해당하는 행위\n가. 금융소비자로부터 계약의 체결권유를 해줄 것을 요청받지 아니하고 방문 전화 등\n실시간 대화의 방법을 이용하는 행위\n나. 계약의 체결권유를 받은 금융소비자가 이를 거부하는 취지의 의사를 표시하였는데\n도 계약의 체결권유를 계속하는 행위",
        "sourceText": "83. 금융소비자보호법에서 정하고 있는 금융투자회사의 부당권유금지와 관련한 내용으로 옳\n지 않은 것은? (★★☆)\n① 보호받을 수 있는 대상은 일반금융소비자와 전문금융소비자에게 해당한다,\n② 장외파생상품을 방문판매하기 위하여 전문금융소비자에게는 사전연락을 할 수 있다.\n③ 적합성의 원칙을 적용받지 아니하고 권유하기 위해 일반금융소비자로부터 계약체결의\n권유를 원하지 않는다는 의사를 서면 등으로 받는 행위를 하여서는 아니된다.\n④ 투자성 상품에 관한 계약체결을 권유하면서 일반금융소비자가 요청하지 않은 다른 대출\n성상품을 안내하거나 관련정보를 제공해서는 안된다.",
