        "difficulty": 2,
        "question": "다음 중 상법상 변태설립사항에 속하는 것은 모두 몇 개인가?",
        "options": [
          "2개",
          "3개",
          "4개",
          "모두 다 해당"
        ],
        "correctAnswer": 3,
        "answerNote": null,
        "explanation": "상법 제290조(변태설립사항)은 정관에 기재함으로써 그 효력이 있다. (e)를 제외한 모두가\n변태설립사항(상대적 기재사항)이다.\n주식회사 설립시 발기인이 받을 특별이익은 변태설립사항으로서 상대적 기재사항이다. 상\n대적 기재사항이란 기재하지 않더라도 정관 자체의 효력에는 영향을 미치지 않지만 해당\n사항이 정관에 기재되어야만 비로소 회사와의 관계에서 그 효력이 발생되는 사항이며 상법\n의 규정 중에 산재(ㅄ쇼)되어 있다.\n-> 변태설립사항(※함효표)이란 회사설립과 관련된 사항들 가운데 회사의 자본적 기\n초를 약화시킬 우려가 있는 것을 말한다. 상법은 회사의 자본을 충실하게 하기 위해 변태\n설립사항의 정관 기재를 강행규정으로 하고 있으며 이를 위반한 경우 원칙적으로 무효이\n다. 변태설립사항에는 발기인의 특별이익, 현물출자, 재산인수, 설립비용과 발기인의 보수\n등이 있다.\n※상법 제289조(주식회사 정관의 작성, 절대적 기재사항)\n발기인은 정관을 작성하여 다음의 사항을 적고 각 발기인이 기명날인 또는 서명하\n여야 한다.\n1. 목적\n2. 상호\n3. 회사가 발행할 주식의 총수\n4. 액면주식을 발행하는 경우 1주의 금액\n(※>100원 이상이어야 한다. 그러나 무액면주식일 경우에는 1주의 금액이 있을 수\n없으므로 1주의 금액은 액면주식을 발행하는 경우에만 이를 절대적 기재사항으로 하\n고 있다. -*기출지문 내용임)\n5. 회사의 설립 시에 발행하는 주식의 총수\n6. 본점의 소재지\n7. 회사가 공고를 하는 방법\n8. 발기인의 성명 • 주민등록번호 및 주소\n※ 상법 제290조(변태설립사항)\n다음의 사항은 정관에 기재함으로써 그 효력이 있다.\n1. 발기인이 받을 특별이익과 이를 받을 자의 성명\n2. 현물출자를 하는 자의 성명과 그 목적인 재산의 종류, 수량, 가격과 이에 대하여\n부여할 주식의 종류와 수\n3. 회사성립후에 양수할 것을 약정한 재산의 종류, 수량, 가격과 그 양도인의 성명\n4. 회사가 부담할 설립비용과 발기인이 받을 보수액",
        "sourceText": "90. 다음 중 상법상 변태설립사항에 속하는 것은 모두 몇 개인가? (★★☆)\na. 발기인이 받을 특별이익과 이를 받을 자의 성명\nb. 현물출자를 하는 자의 성명과 그 목적인 재산의 종류, 수량, 가격과 이에 대하여\n부여할 주식의 종류와 수\nc. 회사성립후에 양수할 것을 약정한 재산의 종류, 수량, 가격과 그 양도인의 성명\nd. 회사가 부담할 설립비용과 발기인이 받을 보수액\ne. 발기인의 성명ㆍ주민등록번호 및 주소\n① 2개\n② 3개\n③ 4개\n④ 모두 다 해당",
