          "회사가 이사에 대하여 또는 이사가 회사에 대하여 소를 제기하는 경우에 감사는 그 소에 관하여 회사를 대표한다.",
          "감사는 이사회 출석 및 의견진술권이 있으므로 감사도 소집통지를 받을 권한이 있다.",
