        "correctAnswer": 1,
        "answerNote": null,
        "explanation": "감사의 자격에는 제한이 없으나 회사 및 자회사의 이사 또는 지배인 기타의 사용인은\n그 성질상 감사가 될 수 없다.\n•상법 제409조(감사의 선임) ①감사는 주주총회에서 선임한다.\n②의결권없는 주식을 제외한 발행주식의 총수의 100분의 3(정관에서 더 낮은 주식 보\n유비율을 정할 수 있으며, 정관에서 더 낮은 주식 보유비율을 정한 경우에는 그 비율\n로 한다)을 초과하는 수의 주식을 가진 주주는 그 초과하는 주식에 관하여 제1항의 감\n사의 선임에 있어서는 의결권을 행사하지 못한다.\n•상법 제410조(임기) 감사의 임기는 취임후 3년내의 최종의 결산기에 관한 정기총회\n의 종결시까지로 한다.\n•상법 제411조(겸임금지) 감사는 회사 및 자회사의 이사 또는 지배인 기타의 사용인\n의 직무를 겸하지 못한다.",
        "sourceText": "91. 우리나라 회사법에 의한 감사에 대한 설명으로 옳지 않은 것은? (★★☆)\n① 감사의 자격에는 제한이 없으므로 자회사의 지배인과 기타의 사용인도 감사가 될 수 있\n다.\n② 회사가 이사에 대하여 또는 이사가 회사에 대하여 소를 제기하는 경우에 감사는 그 소에\n관하여 회사를 대표한다.\n③ 감사는 이사회 출석 및 의견진술권이 있으므로 감사도 소집통지를 받을 권한이 있다.\n④ 모회사 감사는 그 직무를 수행하기 위하여 필요한 경우 자회사에 대하여 영업보고를 요\n구할 수 있고 그 보고내용을 확인하기 위하여 자회사의 업무와 재산상태를 조사할 수도\n있다.",
