        "question": "다음 중 간접세에 해당하지 않는 것은?",
        "options": [
          "종합부동산세",
          "부가가치세",
          "증권거래세",
          "개별소비세"
        ],
        "correctAnswer": 1,
        "answerNote": null,
        "explanation": "종합부동산세는 직접세이다.\n(1) 직접세: 납세부담자와 신고납부자가 동일한 조세로서 소득세, 법인세, 상속 및 증여세,\n종합부동산세 등'이 있다.\n(2) 간접세: 납세부담자와 신고납부자가 다른 조세로서 '부가가치세, 증권거래세, 개별소비\n세, 주세, 인지세 등'이 있다.\n※우리나라 조세체계\n1) 국세(14개)\n개인이 얻은 소득에 부과하는 소득세, 법인에게 부과하는 법인세, 무상으로 이전되는 상속\n세,재산이 무상으로 이전되는 증여세, 부동산에 대한 종합부동산세, 생산• 유통과정에 대한\n부가가치세,특정한 물품에 대한 개별소비세, 주류에 대하여 부과되는 주세, 재산 권리 변동\n증서에 대한 인지세, 주권,지분 양도에 대한 증권거래세, 교육재정 확충에 필요한 교육세,\n사회간접자본투자를 위한 교통에너지환경세, 농어촌특별세, 외국물품 반입 및 물품에 대한\n관세.\n2) 지방세(11개)\n일정한 자산의 취득에 대한 취득세, 재산권, 권리에 대한 등록면허세, 경륜, 경정,경마 등에\n대한 레저세,담배에 과세되는 세금인 담배소비세,지역경제 활성화를 위한 지방소비세, 거주\n하는 개인•법인에 대한 주민세, 납세자의 소득에 따른 지방소득세, 일정한 재산에 대하여 부\n과되는 재산세, 자동차 소유에 대한 자동차세, 지역균형개발•수질개선에대한 지역자원시설\n세, 교육질적향상에 대한 지방교육세",
        "sourceText": "96. 다음 중 간접세에 해당하지 않는 것은? (★★☆)\n① 종합부동산세\n② 부가가치세\n③ 증권거래세\n④ 개별소비세",
