        "explanation": "루카스는 케인즈 이론을 비판한 새고전학파이다. 루카스 비판(Lucas critique)이란 경제 정\n책 평가에 있어 경제주체(개인, 기업 등)의 기대를 고려하지 않은 (케인즈학파의) 전통적 거시\n계량경제모형(소비함수,투자함수 등)은 신뢰할 수 없다고 비판한 경제학자 로버트 루카스의\n주장이다. '루카스 비판'은 정부가 어떤 효과를 기대하고 정책을 펼 경우 이에 맞서는 개인\n또는 기업은 비록(미래를 예측할 수는 없는) 불확실성하에서도 자기나름의 '합리적 기대'를\n하므로 정부가 예측한 방향으로 경제주체들이 움직이지 않는 것을 말한다 ( 정부의 정책에\n속지 않는다는 뜻)",
