        "correctAnswer": 3,
        "answerNote": null,
        "explanation": "발행인에게 회계, 자문 등의 용역을 제공하고 있는 공인회계사 • 감정인 • 변호사 • 변리사 • 세\n무사 등 공인된 자격증을 가지고 있는 자는 50인 산정에서 제외된다\n50인을 산출하는 경우에는 청약의 권유를 하는 날 이전 6개월 이내에 해당 증권과 같은 종류\n의 증권에 대하여 모집이나 매출에 의하지 아니하고 청약의 권유를 받은 자를 합산한다. 다만, 다\n음 각 호의 어느 하나에 해당하는 자는 합산 대상자에서 제외한다.\n1. 다음 각 목의 어느 하나에 해당하는 전문가\n가. 전문투자자\n나. 「공인회계사법」에 따른 회계법인\n다. 신용평가회사법에 따라 신용평가업인가를 받은 자\n라. 발행인에게 회계, 자문 등의 용역을 제공하고 있는 공인회계사 • 감정인 • 변호사 • 변리사 •\n세무사 등 공인된 자격증을 가지고 있는 자\n바. 그 밖에 발행인의 재무상황이나 사업내용 등을 잘 알 수 있는 전문가로서 금융위원회가 정\n하여 고시하는자\n2. 다음 각 목의 어느 하나에 해당하는 연고자\n가. 발행인의 최대주주와 발행주식 총수의 100분의 5 이상을 소유한 주주\n나. 발행인의 임원 및 우리사주조합원\n다. 발행인의 계열회사와 그 임원\n라. 발행인이 주권비상장법인(주권을 모집하거나 매출한 실적이 있는 법인은 제외한다)인 경우\n에는 그 주주\n마. 외국 법령에 따라 설립된 외국 기업인 발행인이 종업원의 복지증진을 위한 주식매수제도\n등에 따라 국내 계열회사의 임직원에게 해당 외국 기업의 주식을 매각하는 경우에는 그 국내 계\n열회사의 임직원\n바. 발행인이 설립 중인 회사인 경우에는 그 발기인\n사. 그 밖에 발행인의 재무상황이나 사업내용 등을 잘 알 수 있는 연고자로서 금융위원회가 정\n하여 고시하는자",
        "sourceText": null,
