        "category": "2과목: 증권시장",
        "difficulty": 2,
        "question": "다음 중 한국거래소의 최소 호가단위(tick size)는?",
        "options": [
          "1원",
          "5원",
          "10원",
          "20원"
        ],
        "correctAnswer": 1,
        "answerNote": null,
        "explanation": "한국거래소의 유가증권시장/코스닥시장/코넥스 시장의 호가가격단위는 공통적이다\n2,000원 미만의 주식은 호가가격단위는 1원으로 가장 작다. 500,000 원 이상의 주가의 호가\n단위는 1,000 원으로 가장 크다.\n※ELW(주식워런트증권)는 상품가격의 특성(옵션의 성격이 내재됨)으로 10주 단위로 거래\n되며, 가격범위와 무관하게 5원 단위로 일괄적용한다. 또한 증권이지만 (위험상품으로 간\n주되어) 기본예탁금제도가 있다 (2025년 개정 기본서에서 ELW를 매우 강조하므로 이에\n대한 이해도를 높혀야 한다)",
