        "category": "2과목: 증권시장",
        "difficulty": 2,
        "question": "다음의 설명에 해당하는 시장경보제도의 지정요건에 해당하는 것은?",
        "options": [
          "투자주의종목",
          "투자경고종목",
          "투자위험종목",
          "투자과열종목"
        ],
        "correctAnswer": 1,
        "answerNote": null,
        "explanation": "동 설명은 투자주의종목에 해당한다.\n한국거래소의 시장감시위원회는 투기적이거나 불공정거래의 개연성이 있는 종목을 투자주의\n종목으로 공표하여 일반 투자자들의 뇌동매매 방지 및 잠재적 불공정거래 행위자에 대한\n경각심을 고취시키고 있다\n투자경고종목이란?\n특정종목의 주가가 비정상적으로 급등한 경우 투자자에게 주의를 환기시키고 불공정거래\n를 사전에 방지하기 위하여 투자경고종목으로 지정한다.\n이는 가수요를 억제하고 주가급등을 진정시키는 등 시장안정화를 위한 조치이다.\n투자경고종목으로 지정되면\n해당종목을 매수할 경우 위탁증거금을 100% 납부하여야 하며\n신용융자로 해당종목을 매수할 수 없으며\n해당종목은 대용증권으로 인정되지 않는다.\n투자위험종목이란?\n투자경고종목 지정에도 불구하고 투기적인 가수요 및 뇌동매매가 진정되지 않고 주가가\n지속적으로 상승할 경우 투자위험종목으로 지정한다.\n이는 한차원 높은 시장경보로서 투자자들은 해당종목 투자시 보다 깊은 주의가 필요하다.\n투자위험종목으로 지정되면\n해당종목을 매수할 경우 위탁증거금을 100% 납부하여야 하며\n신용융자로 해당종목을 매수할 수 없으며\n해당종목은 대용증권으로 인정되지 않는다",
