        "id": 33,
        "category": "2과목: 증권시장",
        "difficulty": 3,
        "question": "커버드본드에 대한 설명으로 옳지 않은 것은?",
        "options": [
          "발행 금융기관은 금리 상승기에 상대적으로 낮은 금리로 자금조달이 가능하다.",
          "은행이 커버드본드를 발행할 경우 고유동성으로 분류하므로 바젤Ⅲ 규정에 의한 은행의 LCR 산정 시 유리하다.",
          "커버드본드의 기초자산에 가계신용대출을 포함하여 낮은 금리로 발행이 가능하다.",
          "담보로 제공된 우량자산에 대한 우선변제권이 인정됨에 따라 발행기관이 부실화되는 경우 예금자 및 일반채권자 등이 상대적으로 불리해 질 수 있다."
        ],
        "correctAnswer": 3,
        "answerNote": null,
        "explanation": "커버드본드의 기초자산에는 일반적으로 신용도가 낮은 가계신용대출, 중소기업대출을 포함시킬\n수 없다. 주로 주택담보대출, 국채나 지방채, 선박, 항공기 그리고 현금이나 CD(만기 100일\n이내), 3개월이내에 현금화가 가능한 자산(예적금) 등으로 구성된다.\n※ 이중상환청구권부 채권 발행에 관한 법률 ( 약칭: 이중상환채권법 )\n이중상환청구권부 채권\"(커버드본드, Covered Bond)이란 발행기관에 대한 상환청구권과\n함께 발행기관이 담보로 제공하는 기초자산집합에 대하여 제3자에 우선하여 변제받을\n권리를 가지는 채권으로서 이 법에 따라 발행되는 것을 말한다.\n\"기초자산집합\"(커버풀, Cover Pool)이란 이중상환청구권부 채권의 원리금 상환을 담보하\n는 자산으로서 등록된 것을 말한다.",
