        "correctAnswer": 2,
        "answerNote": null,
        "explanation": "주된 영업이 6개월 이상 정지되어 잔여사업 부문만으로는 실질적인 영업을 영위하기 어렵거\n나 영업의 전부가 양도되는 경우에는 등록: 지정해제 사유에 해당한다.\n※ K-OTC 등록 또는 지정해제 사유\n1. 발행한 어음 또는 수표가 거래은행에 의하여 최종부도로 결정되거나 거래은행과의 거래\n가 정지된 경우\n2. 최근 사업연도말을 기준으로 자본전액잠식 상태인 경우. 다만, 결산기 정기공시서류의 제\n출기한까지 협회장이 정하는 바에 따라 자본전액잠식 상태를 해소하였음이 확인된 경우\n는 제외\n3. 최근 사업연도 매출액이 1억원 미만이거나 최근 2개 사업연도에 연속하여 매출액이 5억\n원(크라우드펀딩 특례 적용 기업의 경우 3억원) 미만인 경우\n4. 최근 사업연도의 재무제표에 대한 감사인의 감사의견이 부적정, 의견거절이거나 최근 2\n개 사업연도에 연속하여 감사범위제한으로 인한 한정인 경우\n5. 주된 영업이 6개월 이상 정지되어 잔여사업 부문만으로는 실질적인 영업을 영위하기 어\n렵거나 영업의 전부가 양도되는 경우.\n6. 「채무자 회생 및 파산에 관한 법률』에 따른 법원의 회생절차개시신청 기각, 회생절차개\n시결정 취소, 회생계획인가 및 회생절차폐지 결정이 있는 경우. 다만, 「채무자 회생 및\n파산에 관한 법률』 제287조에 따른 회생절차폐지의 경우에는 적용하지 않음\n7. 정기공시서류 제출과 관련하여 다음 각 목의 어느 하나에 해당하는 경우\n가. 결산기 정기공시서류를 제출기한까지 제출하지 아니한 후 제출기한의 다음 날부터 30\n일 이내에 제출 하지 아니한 경우\n나. 반기 정기공시서류를 최근 4개 사업연도에 1회 이상 제출기한까지 제출하지 아니한 법\n인이 최근 반기에 반기 정기공시서류를 제출기한까지 제출하지 아니한 후 제출기한의\n다음 날부터 15일 이내에 제출하지 아니한 경우\n8. 증권시장에 상장되는 경우\n다음은 협회가 규정상 표시한 등록 및 지정의 해제 사유이다\n1. 최근 사업연도말 현재 자본전액잠식(최근 사업연도말 이후부터 등록신청일까지의 유\n상증자금액 및 자산재평가에 의하여 자본에 전입할 금액을 반영한다) 상태가 아닐 것\n(저자 주: 회계적으로 자본잠식과 자본전액잠식은 다르다. 회사법 강의를 참고하기 바람)\n2. 최근 사업연도의 매출액(재화의 판매와 용역의 제공금액을 합산한 금액을 말한다. 이\n하 같다)이 5억원 이상일 것. 다만, 신규등록신청일 현재 크라우드펀딩의 방법으로 발행한\n주권[보통주식(신규등록신청 전에 보통주식으로 전환된 종류주식을 포함한다)에 대한 주권\n을 말한다]의 금액(이하 크라우드펀딩금액\"이라 한다)이 2억원 이상으로서 법 제9조제27항\n각 호 외의 부분 본문에 따른 온라인소액투자중개업자(이하 크라우드펀딩중개업자\"라 한\n다)로부터 K-OTC시장 신규등록 추천을 받은 크라우드펀딩기업의 경우에는 최근 사업연도\n의 매출액을 3억원 이상으로 한다.\n3. 최근 사업연도의 재무제표에 대한 감사인의 감사의견이 적정일 것\n4. 정관 등에 주식양도의 제한이 없을 것. 다만, 다른 법령에 따라 제한되는 경우로서\n그 제한이 K-OTC시장에서의 매매거래를 해치지 아니한다고 인정된 경우에는 그러하지 아\n니하다.",
