        "explanation": "준법감시인의 임기는 2년 이상으로 한다\n준법감시인의 임기는 2년 이상으로 하며 임면일로부터 7영업일 이내에 금융위원회에 보고하\n여야 한다 ( 미보고 시 3천만원 이하의 과태료 대상임)\n※금융사지배구조법 제25조(준법감시인의 임면 등)\n① 금융회사(자산규모 등을 고려하여 대통령령으로 정하는 투자자문업자 및 투자일임업자는\n제외한다)는 내부통제기준의 준수 여부를 점검하고 내부통제기준을 위반하는 경우 이를\n조사하는 등 내부통제 관련 업무를 총괄하는 사람(준법감시인)을 1명 이상 두어야 하며,\n준법감시인은 필요하다고 판단하는 경우 조사결과를 감사위원회 또는 감사에게 보고할\n수 있다.\n② 금융회사는 사내이사 또는 업무집행책임자 중에서 준법감시인을 선임하여야 한다. 다만,\n자산규모, 영위하는 금융업무 등을 고려하여 대통령령으로 정하는 금융회사 또는 외국금\n융회사의 국내지점은 사내이사 또는 업무집행책임자가 아닌 직원 중에서 준법감시인을\n선임할 수 있다.\n③ 금융회사(외국금융회사의 국내지점은 제외한다)가 준법감시인을 임면하려는 경우에는 이\n사회의 의결을 거쳐야 하며, 해임할 경우에는 이사 총수의 3분의 2 이상의 찬성으로 의\n결한다.\n④ 준법감시인의 임기는 2년 이상으로 한다.\n⑤ 금융회사는 준법감시인을 제2항 단서에 따라 직원 중에서 선임하는 경우 「기간제 및 단\n시간근로자 보호 등에 관한 법률』에 따른 기간제근로자 또는 단시간근로자를 준법감시인\n으로 선임하여서는 아니 된다.\n⑥ 금융회사는 준법감시인에 대하여 회사의 재무적 경영성과와 연동하지 아니하는 별도의\n보수지급 및 평가 기준을 마련하여 운영하여야 한다.\n(시행령)제25조(준법감시인 및 위험관리책임자의 임면에 따른 보고)\n① 금융회사는 준법감시인 또는 위험관리책임자를 임면하였을 때에는 그 사실을 금융위원회\n에 임면일부터 7영업일 이내에 보고하여야 한다.",
