        "answerNote": null,
        "explanation": "영업의 전부 또는 일부의 양도는 경영개선 명령에 해당한다.\n※ 금융투자업규정에서 정하는 경영의 권고• 개선: 요구의 주요내용\n제3-26조(경영개선권고)\n1. 인력 및 조직운용의 개선,2. 경비절감, 3. 점포관리의 효율화 ,4. 부실자산의 처분.\n5. 영업용순자본감소행위의 제한, 6. 신규업무 진출의 제한. 7. 자본금의 증액 또는 감액,\n8. 대손충당금 등의 설정\n제3-27조(경영개선요구)\n1. 고위험자산보유제한 및 자산처분, 2. 점포의 폐쇄, 통합 또는 신설제한, 3. 조직의 축\n소, 4. 자회사의 정리, 5. 임원진 교체 요구, 6. 영업의 일부정지, 7. 합병 • 제3자 인수\n영업의 전부 또는 일부의 양도. 「금융지주회사법」에 따른 금융지주회사의 자회사로의 편\n입에 관한 계획수립\n제3-28조(경영개선명령)\n1. 주식의 일부 또는 전부소각, 2. 임원의 직무집행 정지 및 관리인 선임, 3. 합병, 금융지\n주회사의 자회사로의 편입, 4. 영업의 전부 또는 일부의 양도. 5. 제3자의 당해 금융투자\n업 인수, 6. 6개월 이내의 영업정지. 7. 계약의 전부 또는 일부의 이전",
