        "correctAnswer": 3,
        "answerNote": null,
        "explanation": "신탁업무는 해당하지 아니한다. (기출문제임)\n1. 종합금융투자사업자가 아니고는 전담중개업무(프라임브로커)를 영위할 수 없다.\n2. 종합금융투자사업자는 일반 사모집합투자기구등 중 투자대상, 차입 여부 등을 감안하여\n전담중개업무를 제공하는 경우에는 미리 해당 일반 사모집합투자기구등과 다음의 사항을\n포함하는 내용에 관한 계약을 체결하여야 한다.\n1) 전담중개업무와 관련된 종합금융투자사업자와 일반 사모집합투자기구등의 역할 및 책임\n에 관한 사항\n2) 종합금융투자사업자가 일반 사모집합투자기구등의 재산을 제삼자에 대한 담보, 대여.\n그 밖에 대통령령으로 정하는 방법으로 이용하는 경우 그 이용에 관한 사항\n3) 종합금융투자사업자가 제2호에 따라 이용한 일반 사모집합투자기구등의 재산 현황 등에\n관한 정보를 일반 사모집합투자기구등에게 제공하는 절차 및 방법\n4. 그 밖에 대통령령으로 정하는 사항\n3. 종합금융투자사업자는 이 법 또는 다른 금융관련 법령에도 불구하고 다음 각 호의 업무\n를 영위할 수 있다.\n1. 기업에 대한 신용공여 업무 ( 이는 증권사가 은행의 업무영역을 넘보는 업무임)\n2. 그 밖에 해당 종합금융투자사업자의 건전성, 해당 업무의 효율적 수행에 이바지할 가능\n성 등을 고려하여 종합금융투자사업자에만 허용하는 것이 적합한 업무로서 대통령령으로\n정하는 것",
