        "explanation": "금융감독원은 광고주체가 아니다\n투자성상품의 경우 금융상품판매대리•중개업자는 광고를 수행할 수 없다.(왜냐하면 개인인\n투자권유대행인이 이에 해당하고 1사 전속이므로 본인이 따로 광고할 수 없다)\n금소법, 제17조(광고의 주체)\n법 제22조제1항 각 호 외의 부분 단서에서 \"금융상품판매업자등을 자회사 또는 손자회\n사로 하는 금융지주회사 등 대통령령으로 정하는 자란 다음 각 호의 자를 말한다.\n1. 금융상품판매업자등을 자회사 또는 손자회사로 하는 금융지주회사\n2. 「자본시장과 금융투자업에 관한 법률』에 따른 증권의 발행인 또는 매출인(해당 증권에\n관한 광고를 하는 경우로 한정한다)\n3. 「주택도시기금법」에 따른 주택도시보증공사\n4. 「한국주택금융공사법」에 따른 한국주택금융공사\n5. 집합투자업자\n6. 그 밖에 제1호부터 제5호까지의 자에 준하는 자로서 금융위원회가 정하여 고시하는 자",
