          "임원 주요주주 소유상황보고가 면제되는 경미한 변동의 기준은 변동수량 1천주 미만, 그 취득 및 처분금액이 1천만원 미만이다.",
          "주요주주가 특정증권등을 매수한 후 6개월 이내에 매도하거나 특정증권등을 매도한 후 6개월 이내에 매수하여 이익을 얻은 경우에는 그 법인은 그 임직원 또는 주요주주에게 그 이익(“단기매매차익”)을 그 법인에게 반환할 것을 청구할 수 있다",
          "차입한 상장증권으로 결제하고자 하는 매도는 공매도에 해당하지 아니한다."
