        "correctAnswer": 4,
        "answerNote": null,
        "explanation": "- 자본시장법 제180조(공매도의 제한) 누구든지 증권시장(다자간매매체결회사에서의 증권\n의 매매거래를 포함)에서 상장증권에 대하여 다음 각 호의 어느 하나에 해당하는 매도(\"공\n매도\"라 한다)를 하거나 그 위탁 또는 수탁을 하여서는 아니 된다. 다만, 제2호에 해당하는\n경우로서(\"차입공매도\"라 한다) 증권시장의 안정성 및 공정한 가격형성을 위하여 대통령령\n으로 정하는 방법에 따르는 경우에는 이를 할 수 있다.\n1. 소유하지 아니한 상장증권의 매도\n2. 차입한 상장증권으로 결제하고자 하는 매도\n② 제1항 본문에 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 이를 공매도로 보지\n아니한다.\n1. 증권시장에서 매수계약이 체결된 상장증권을 해당 수량의 범위에서 결제일 전에 매도하는\n경우\n2. 전환사채 • 교환사채 신주인수권부사채 등의 권리 행사, 유• 무상증자, 주식배당 등으로\n취득할 주식을 매도하는 경우로서 결제일까지 그 주식이 상장되어 결제가 가능한 경우\n3. 그 밖에 결제를 이행하지 아니할 우려가 없는 경우로서 대통령령으로 정하는 경우\n③ 금융위원회는 증권시장의 안정성 및 공정한 가격형성을 저해할 우려가 있는 경우에는 거\n래소의 요청에 따라 상장증권의 범위, 매매거래의 유형 및 기한 등을 정하여 차입공매도\n를 제한할 수 있다.\n- 자본시장법 제174조(미공개중요정보 이용행위 금지) ① 다음 각 호의 어느 하나에 해당\n하는 자(제1호부터 제5호까지의 어느 하나의 자에 해당하지 아니하게 된 날부터 1년이 경\n과하지 아니한 자를 포함한다)는 상장법인[6개월 이내에 상장하는 법인 또는 6개월 이내에\n상장법인과의 합병, 주식의 포괄적 교환, 그 밖에 대통령령으로 정하는 기업결합 방법에\n따라 상장되는 효과가 있는 비상장법인(\"상장예정법인등\")을 포함한다]\n1. 그 법인(그 계열회사를 포함한다. 이하 이 호 및 제2호에서 같다) 및 그 법인의 임직원\n• 대리인으로서 그 직무와 관련하여 미공개중요정보를 알게 된 자\n2. 그 법인의 주요주주로서 그 권리를 행사하는 과정에서 미공개중요정보를 알게 된 자\n3. 그 법인에 대하여 법령에 따른 허가 • 인가 • 지도 • 감독, 그 밖의 권한을 가지는 자로서\n그 권한을 행사하는 과정에서 미공개중요정보를 알게 된 자\n4. 그 법인과 계약을 체결하고 있거나 체결을 교섭하고 있는 자로서 그 계약을 체결 • 교섭\n또는 이행하는 과정에서 미공개중요정보를 알게 된 자\n5. 제2호부터 제4호까지의 어느 하나에 해당하는 자의 대리인(이에 해당하는 자가 법인인\n경우에는 그 임직원 및 대리인을 포함한다) • 사용인, 그 밖의 종업원(제2호부터 제4호까지\n의 어느 하나에 해당하는 자가 법인인 경우에는 그 임직원 및 대리인)으로서 그 직무와 관\n련하여 미공개중요정보를 알게 된 자\n6. 제1호부터 제5호까지의 어느 하나에 해당하는 자(제1호부터 제5호까지의 어느 하나의\n자에 해당하지 아니하게 된 날부터 1년이 경과하지 아니한 자를 포함한다)로부터 미공개중\n요정보를 받은 자\n- 자본시장법 제173조(임원 등의 특정증권등 소유상황 보고) ① 주권상장법인의 임원 또는\n주요주주는 임원 또는 주요주주가 된 날부터 5일 이내에 누구의 명의로 하든지 자기의 계\n산으로 소유하고 있는 특정증권등의 소유상황을, 그 특정증권등의 소유상황에 변동이 있는\n경우에는 그 변동이 있는 날부터 5일까지 그 내용을 증권선물위원회와 거래소에 보고하여\n야 한다. 다만, 특정증권등의 변동 수량이 1천주 미만이고. 그 취득 또는 처분금액이 1천\n만원 미만인 경우는 보고를 면제한다\n- 자본시장법, 194조(단기매매차익 반환대상 직원의 범위) 미공개중요정보를 알 수 있는 자\n느 다음과 같다.\n1. 그 법인에서 주요사항보고 대상에 해당하는 사항의 수립 • 변경 • 추진 • 공시, 그 밖에\n이에 관련된 업무에 종사하고 있는 직원\n2. 그 법인의 재무 • 회계 • 기획 • 연구개발에 관련된 업무에 종사하고 있는 직원 (<주의:\n생산직은 대상이 아님)",
