        "correctAnswer": 4,
        "answerNote": null,
        "explanation": "최종적으로 남은 잔여주식은 기관투자자에게 배정한다.\n->기업공개시의 주식배정과 공모증자시 주식배정 방식이 다름에 유의한다 (기본서 내용 참조)\n① 기업공개(IPO)를 위한 대표주관회사는 공모주식을 다음 각 호에서 정하는 바에 따라 해\n당 청약자 유형군에 배정하여야 한다.\n1. 유가증권시장 상장을 위한 기업공개(외국법인등의 기업공개는 제외한다)의 경우 우리사\n주 조합원에게 「근로복지기본법』 제38조제1항에 따라 공모주식의 20%를 배정한다.\n2. 코스닥시장 또는 코넥스시장 상장을 위한 기업공개의 경우 우리사주 조합원에게 공모주\n식의 20%를 배정할 수 있다. (< 배정안해도 된다는 의미)\n3. 일반청약자에게 공모주식의 25% 이상을 배정한다.\n4. 고위험고수익투자신탁등[고위험고수익채권투자신탁의 경우에는 공모주식의 5% 이상을\n배정한다. 다만, 코스닥시장 상장을 위한 기업공개의 경우에는 10% 이상을 배정한다.\n5. 코스닥시장 상장을 위한 기업공개의 경우 벤처기업투자신탁(사모의 방법으로 설정된 벤\n처기업투자신탁의 경우 최초 설정일로부터 1년 6개월 이상의 기간 동안 환매가 금지된 벤\n처기업투자신탁을 말한다)에 공모주식의 25% 이상을 배정한다.\n6. 제1호 또는 제2호에도 불구하고 우리사주 조합원이 공모주식의 20% 미만을 청약하는\n경우 공모주식의 20%에서 우리사주 조합원의 청약수량을 제외한 주식(이하 우리사주 잔\n여주식\"이라 한다)을 공모주식의 5% 이내에서 일반청약자에게 배정할 수 있다. 이 경우 우\n리사주 조합원이 공모주식의 20% 미만을 청약한 사유 등을 감안하여 발행인과 협의하여\n야 한다.\n7. 제1호부터 제6호에 따른 배정 후 잔여주식은 기관투자자에게 배정한다.",
