        "category": "4과목: 법규 및 세제",
        "difficulty": 3,
        "question": "다음 중 우리나라 상법 상 주식에 대한 설명으로 옳은 것은 모두 몇 개인가?",
        "options": [
          "1 개",
          "2 개",
          "3 개",
          "4 개"
        ],
        "correctAnswer": 2,
        "answerNote": null,
        "explanation": "A 이익의 배당,잔여재산의 분배, 주주총회에서 의결권의 행사, 상환 및 전환에 대하여\n종류주식을 발행할 수 있다 (O)\n상법 제344조(종류주식) ① 회사는 이익의 배당, 잔여재산의 분배, 주주총회에서의 의결권\n의 행사, 상환 및 전환 등에 관하여 내용이 다른 종류의 주식(이하 종류주식\"이라 한다)\n을 발행할 수 있다.\n② 제1항의 경우에는 정관으로 각 종류주식의 내용과 수를 정하여야 한다.\n③ 회사가 종류주식을 발행하는 때에는 정관에 다른 정함이 없는 경우에도 주식의 종류에\n따라 신주의 인수, 주식의 병합 • 분할• 소각 또는 회사의 합병 • 분할로 인한 주식의 배정\n에 관하여 특수하게 정할 수 있다.(차별이 가능하다는 뜻임)\nq 종류주식 주주의 종류주주총회의 결의에 관하여는 제435조제2항을 준용한다\n® 기명주식과 무기명 주식의 발행이 가능하다(X): 무기명주식을 발행할 수 없다\n© 액면주식과 무액면주식간의 전환이 가능하다 (o)\n상법 제329조(자본금의 구성) ① 회사는 정관으로 정한 경우에는 주식의 전부를 무액면주식\n으로 발행할 수 있다. 다만, 무액면주식을 발행하는 경우에는 액면주식을 발행할 수 없다.\n② 액면주식의 금액은 균일하여야 한다.\n③ 액면주식 1주의 금액은 100원 이상으로 하여야 한다.\n④ 회사는 정관으로 정하는 바에 따라 발행된 액면주식을 무액면주식으로 전환하거나 무액면\n주식을 액면주식으로 전환할 수 있다.\nD 정관으로 정하는 경우 액면주식과 무액면 주식을 모두 발행할 수 있다.(x): 둘 중 하나만\n발행이 가능하다.\n상법 제451조(자본금) ① 회사의 자본금은 이 법에서 달리 규정한 경우 외에는 발행주식\n의 액면총액으로 한다.\n회사가 무액면주식을 발행하는 경우 회사의 자본금은 주식 발행가액의 2분의 1 이상의\n금액으로서 이사회(제416조 단서에서 정한 주식발행의 경우에는 주주총회를 말한다)에서\n자본금으로 계상하기로 한 금액의 총액으로 한다. 이 경우 주식의 발행가액 중 자본금으로\n계상하지 아니하는 금액은 자본준비금으로 계상하여야 한다.\n③ 회사의 자본금은 액면주식을 무액면주식으로 전환하거나 무액면주식을 액면주식으로\n전환함으로써 변경할 수 없다.",
