        "question": "비거주자에 대한 과세방법으로 옳지 않은 것은?",
        "options": [
          "비거주자가 국내사업장이나 부동산소득이 있는지 여부에 따라 과세방법이 달라진다",
          "국내사업장이나 부동산임대소득 등이 있는 비거주자는 국내원천소득(퇴직소득, 양도소득 제외)을 종합과세한다.",
          "국내사업장이나 부동산임대소득 등이 없는 비거주자는 무조건 분리과세한다",
          "퇴직소득ㆍ양도소득의 국내원천소득이 있는 비거주자는 당해 소득별로 분류과세한다."
        ],
        "correctAnswer": 3,
        "answerNote": null,
        "explanation": "국내사업장이나 부동산임대소득 등이 없는 비거주자는 국내원천소득을 분리과세한다.\n※ 금융소득의 경우. 분리과세에는 무조건 분리과세 금융소득, 조건부 분리과세 금융소득(연간\n2,000만원 이하인 경우 원천징수로 과세의무가 끝나므로 종합과세되지 아니한다)이 있다.\n비거주자의 과세방법:\n비거주자가 국내사업장이나 부동산소득이 있는지 여부에 따라 과세방법이 달라진다.\n① 종합과세 : 국내사업장이나 부동산임대소득 등이 있는 비거주자는 국내원천소득\n(퇴직소득, 양도소득 제외)을 종합과세한다.\n② 분리과세 : 국내사업장이나 부동산임대소득 등이 없는 비거주자는 국내원천소득을 분리과세\n한다.\n③ 분류과세 : 퇴직소득. 양도소득의 국내원천소득이 있는 비거주자는 당해 소득별로 분류과세\n한다.\n(가장 최근 출제된 기출복기문제임)",
