        "explanation": "회복(Recovery) - 호황(Boom) - 후퇴(Recession) - 불황(Depression)의 순서이다.\n이 순서는 만약 시험문제에서 불황(Depression)-회복(Recovery) - 호황(Boom) - 후퇴(Recession) 등으로 순서를 바꿀 수 있으므로 주의를 요한다.\n경기순환은 전통적으로 회복(recovery), 호황(boom), 후퇴(recession), 불황(depression)으로 나누는 4분법이 이용되었으나 그 구분을 명확히 구분하기 어렵기 때문에 최근에는 경기저점(trough)에서 정점(peak)까지 경제활동이 활발한 확장국면(expansion)과 경기정점에서 저점까지 경제활동이 위축된 수축국면(contraction)으로 나누는 2분법이 주로 이용된다.",
