        "id": 8,
        "category": "1과목: 증권분석",
        "difficulty": 2,
        "question": "다음은 기업가치분석에서 주가배수를 활용한 기업의 상대가치평가법에 대한 공식이다. A,B,C에 들어갈 용어로 모두 옳은 것은?",
        "options": [
          "A=주당매출총이익, B=주당매출액, C=주당배당액",
          "A=주당영업이익, B=주당배당액, C=주당운전자본",
          "A=주당순이익, B=주당매출원가, C=주당자기자본",
          "A=주당순이익, B=주당매출액, C=주당순자산"
        ],
        "correctAnswer": 4,
        "answerNote": null,
        "explanation": "A=주당순이익, B=주당매출액, C=주당순자산이다\n(1) PER 평가모형:\n주가수익비율(PER: Price Earning Ratio)은 주가를 주당순이익으로 나눈 것이다. 이 지표는 기업의 단위당 수익가치에 대한 상대적인 주가수준을 나타낸 것으로 주당이익에 비하여 주가가 몇 배인지를 나타낸다는 의미에서 이익승수(earnings multiples)라고도 한다.\n(2) PBR 평가모형:\n주가순자산비율(PBR : Price to Book value Ratio)은 주가를 자기자본의 주당장부가치인 주당순자산으로 나눈 비율이다. 여기서 순자산은 총자산에서 보통주에 대한 선순위 지분증권인 부채와 우선주를 차감한 금액이다. PER이 수익가치에 대비한 상대적 주가수준을 나타내는 지표인 반면에, PBR은 자산가치에 대비한 상대적 주가수준을 측정한 지표라는 데 근본적인 차이점이 있다. 또한 PER이 주가와 일정기간 동안 수익이라는 유량(flow)을 나타내고, PBR은 주가와 특정 시점 순자산의 저량(stock)을 나타내는 지표라는 차이가 있다.\n(3) PSR 평가모형:\n기술주는 처음 수년간 이익을 내지 못하여 수익가치를 평가할 수 없는 경우가 많다. 기술관련 우수한 인적자원은 많지만 고정자산 투자가 작아 자산가치를 평가하기가 어려운 경우에 매출액 크기로 평가하는 모형이다. 주가매출액비율(PSR : Price Sales Ratio)은 주가를 주당매출액으로 나눈 것으로, 기업의 외형적인 성과척도인 주당매출액에 비교한 상대적 주가수준을 평가하는 지표이다.",
        "sourceText": "★★☆\n8. 다음은 기업가치분석에서 주가배수를 활용한 기업의 상대가치평가법에 대한 공식이다.\nA,B,C에 들어갈 용어로 모두 옳은 것은?\n가) PER = 주가/( A )\n나) PSR = 주가/( B )\n다) PBR = 주가/( C )\n① A=주당매출총이익, B=주당매출액, C=주당배당액\n② A=주당영업이익, B=주당배당액, C=주당운전자본\n③ A=주당순이익, B=주당매출원가, C=주당자기자본\n④ A=주당순이익, B=주당매출액, C=주당순자산",
