        "explanation": "EV/EBITDA 비율을 말한다.\n※ EV/EBITDA비율의 의의\n(1) PER의 한계점을 보완한다.\n→PER는 당기순이익을 기준으로 평가하지만 EV/EBITDA는 영업이익(주1)을 기준으로 하므로 아래 두가지 관점에서 PER를 보완한다.\n㉠ 당기순손실이지만 영업이익이 흑자인 기업을 평가할 수 있으므로 PER보다 평가 범위가 더 넓다.\n㉡ 둘째 영업이익에 감가상각비를 가산함으로써 PER에서 반영할 수 없는 현금흐름도 보완할 수 있다.\n*(주1): EBITDA는 영업이익(EBIT)에 감가상각비(DA)를 가산한 것을 말함.\n(2) 자본구조를 감안한 평가방식의 의미: 분자항목인 EV는 '시가총액+순차입금'을 말하는데, 이는 '주주가치+채권자가치'를 의미한다. 따라서 자본구조(자기자본/타인자본)를 반영한다.",
