        "explanation": "적삼병에 대한 설명이다. 적삼병은 고점을 높이며 연속된 3개의 강한 양봉이 발생하는 패턴으로, 이 패턴이 나타나면, 바닥권이 발생한 경우 장기간의 하락 추세를 벗어나 상승으로 전환되는 신호로 해석한다.\n반면, 흑삼병은 높은 위치에서 저점을 낮추는 3개의 음종이 연속적으로 발생하는 패턴이다. 이러한 패턴이 나타나면, 매수세에서 매도세로 돌아섬을 의미하여 순간적인 급락세로 돌아서는 가능성이 높기 때문에 주의가 필요한 구간이다.\n사케다전법은 삼산, 삼천, 삼병(적삼병,흑삼병), 삼공, 삼법을 말한다. 이 중에서 삼산, 삼천, 삼병(적삼병, 흑삼병), 삼공은 주가 패턴의 해석에 대한 풀이에 해당하며, 삼법은 행동원리를 의미한다.",
