        "explanation": "SPAC 회사는 기업공개(IPO)를 통해 자본을 모아서 주식시장에 먼저 상장 후, 비상장 주식회사 중에서 유망한 기업을 합병하여 주식시장에 들어올 수 있게 하는 것이다. 결국 SPAC상장을 통하여 비상장기업은 SPAC이 보유한 자금으로 공모자금조달효과를 낼 수 있다.\n※스팩주란 Special Purpose Acquisition Company의 약자로 오로지 기업 인수만을 목적으로하는 페이퍼 컴퍼니의 주식을 뜻한다. SPAC은 투자자로부터 조달한 자금으로 다른 기업을 인수합병(M&A)하여 비상장 주식회사가 주식시장에 상장되도록 만드는 것을 목표로 한다.\n※우회상장(back-door listing)\n증권시장에 상장되어 있지 않은 기업이 정식 상장절차를 거치지 않고 증권시장에 바로 상장되는 것을 뜻하며 영어로는 ‘백 도어 리스팅(back door listing)’이라고 한다.\n비상장기업이 상장을 위한 심사나 공모주청약 등의 정식 절차를 거치지 않고 우회적인 방법을 통해 증권거래소나 코스닥시장 등 증권시장에 진입해 사실상 상장 효과를 누리는 행위를 말한다.\n우회상장은 크게 기업합병, 포괄적 주식교환, 영업양수도, 자산양수, 현물출자의 방법으로 이뤄진다.\n이 가운데 증권시장에 상장되어 있는 기업과의 합병을 통한 우회상장의 대표적인 방법이다. 기업합병에 의한 우회상장은 비상장기업이 상장기업의 최대주주 지분과 경영권을 넘겨받아 최대주주 지위를 확보하고, 합병을 결의한 후 상장기업이 합병의 대가로 비상장기업의 주주에게 상장주식을 발행하는 방식이다.\n포괄적 주식교환은 비상장기업 주주들이 상장기업에 그들의 지분을 모두 넘겨주고, 그 대가로 상장기업의 신주를 받음으로써 상장효과를 얻게 되는 방식이다. 비상장기업이 상장기업의 완전자회사가 되는 경우이다.\n영업양수도 방식은 비상장기업이 그들의 영업 및 관련 자산부채를 모두 상장기업에 넘겨주고 영업양도 대가를 받은 후 해산했다가 이후에 상장기업의 신주발행에 참여해 상장기업의 주주가 되면서 우회상장이 이루어진다.\n우회상장은 상장요건을 충족시키기에는 미흡하지만 성장성이 높고 재무적으로 우량한 비상장기업에 자본조달의 기회를 주려는 취지로 도입된 제도이다. 그러나 우회상장에 대한 심사가 허술할 경우 자격미달의 부실기업이 쉽게 자본시장에 진입하여 투자자들이 피해를 보는 사례가 발생하기도 한다.",
        "sourceText": "★★☆\n18. 다음 중 우회상장(SPAC상장 포함)의 설명으로 옳지 않은 것은?\n① SPAC상장을 통하여 비상장기업이 보유한 자금으로 공모자금조달효과를 낼 수 있다.\n② SPAC 상장은 우량 비상장기업의 건전한 우회상장을 위한 것이다.\n③ 상장적격성을 충족하지 못하는 비상장기업의 우회상장 방지를 위하여 거래소는 신규상장\n수준의 질적심사제도를 적용한다.\n④ 우회상장으로 비상장회사의 잠재적 부실을 떠안을 수도 있다.",
