        "explanation": "기세(氣勢) 제도에 대한 설명이다.\n기세는 장이 마감될 때까지 거래가 없었던 종목에서 당일 기준 가격을 중심으로 높은 매수가(또는 낮은 매도가)가 있다면 가장 높은 매수 호가(또는 낮은 매도 호가)를 종가로 인정해주는 제도이다.\n※ (Random End, 랜덤엔드) 모든 단일가매매 시 가격결정을 위한 호가접수시간을 정규마감시간 이후 30초 이내에 임의시간을 연장하여 매매체결 시점이 임의적으로 결정되도록 하는 제도를 단일가매매 임의연장(Random End, 랜덤엔드)라고 한다.\n이는 단일가매매시간중 허수성 호가에 의한 가격 왜곡문제를 방지하여 선의의 투자자 피해를 최소화하고 시장의 투명성 제고 및 균형가격 발견기능을 강화 하기 위한 것이다.",
        "sourceText": "★★★\n20. 아래의 설명에 해당하는 것은?\n특정 종목에 중요정보가 발생하는 경우에는 매도 또는 매수 일방의 호가만 제출되어서\n매매거래가 체결되지 않을 수 있다. 이 때 유입된 호가를 인정하지 않으면 당일의\n기준가격과 가격제한폭이 다음 날에도 그대로 적용되어 중요정보가 계속해서 주가에\n반영하지 못하고 시장에서 원활하게 매매거래가 이루어질 수 없게 되어 이러한 문제점을\n해소하기 위하여 거래소에서 운영하고 있는 제도이다.\n① 호가의 정정 및 취소 제도\n② 기세 제도\n③ 사이드카 제도\n④ 랜덤엔드 제도",
