        "category": "2과목: 증권시장",
        "difficulty": 2,
        "question": "다음 중 우리나라 국채전문유통시장에 대한 설명으로 옳지 않은 것은?",
        "options": [
          "일반투자자는 기관투자자(국고채전문딜러)를 통한 위탁참여만 가능하다",
          "국채전문 유통시장에서는 매매수량단위가 1억원의 정배수로 거래한다.",
          "거래대금의 이체는 한국은행 BOK Wire를 통한 자금이체방식이다",
          "국채전문 유통시장에서는 국고채권(외평채 포함) 뿐만 아니라 통화안정증권도 거래된다."
        ],
        "correctAnswer": 2,
        "answerNote": null,
        "explanation": "국채전문 유통시장에서는 매매수량단위가 10억원의 정배수로 거래한다.\n국고채는 기획재정부장관이 발행하고 대금결제는 한국은행 BOK-Wire자금이체방식으로 각 금융기관이 한국은행에 개설된 지급준비금계정에서 결제된다 (<이는 외국은행이 우리나라의 금융기관의 신용도 문제로 중앙은행의 직접 자금관리를 요청하기 때문이다: 저자 주)\n~국고채전문딜러(primary dealer) 제도\n국채전문딜러제도란 국고채에 대한 투자매매업을 허가받은 기관(국채딜러)중 자금력과 시장운영의 전문성을 갖춘 전문기관만이 국고채에 대한 시장조성 기능을 담당하게 한 것이다. 기획재정부장관이 지정 운영하고 있으며 국고채 인수 등에 관하여 우선적인 권리를 부여 받는 대신 국고채 전문유통시장에서 시장조성자로 호가제시, 거래 등의 의무를 수행한다.\n국고채전문딜러는 국고채 발행시장에서 국고채 인수 등에 관하여 우선적인 권리를 부여받는 대신 국고채 유통시장에서 시장조성자로서의 의무를 수행하는 국채딜러를 지칭한다.\n국고채전문딜러제도는 국고채시장의 활성화를 통해 금융시장 구조의 선진화를 이루고, 정부의 안정적인 재정기반을 확립하기 위해 도입된 시장조성자 제도로 1999년 도입된 이래 국내 채권시장 발전의 견인차 역할을 해오고 있다.\n국고채전문딜러는 자금력과 국채투자매매업에 전문성을 갖추고 있는 금융기관으로 국고채 발행시장에서 우선적으로 입찰에 참여할 수 있는 권리와 인수·유통금융 등의 지원을 받는 대신 국채유통시장에서 일정한 의무를 수행하여야 한다.\n또한, 기획재정부는 2011년 3월부터 경쟁력 있는 국고채전문딜러(Primary Dealer, PD)를 육성하기 위해 기존의 PD만이 존재하던 PD제도를 개편하여 예비국고채전문딜러(Preliminary Primary Dealer, PPD) 제도를 도입하였다.\n이에 따라 국고채전문딜러로 지정되고 싶은 금융기관은 우선 예비국고채전문딜러로 지정되어야 한다. 예비국고채전문딜러로 지정된 이후 의무이행 실적이 우수한 경우에는 국고채전문딜러로 승격된다. 반대로 국고채전문딜러로 지정되었으나, 이후 의무이행 실적이 부진한 금융기관은 예비국고채전문딜러로 전환된다.",
        "sourceText": "★★☆\n29. 다음 중 우리나라 국채전문유통시장에 대한 설명으로 옳지 않은 것은?\n① 일반투자자는 기관투자자(국고채전문딜러)를 통한 위탁참여만 가능하다\n② 국채전문 유통시장에서는 매매수량단위가 1억원의 정배수로 거래한다.\n③ 거래대금의 이체는 한국은행 BOK Wire를 통한 자금이체방식이다\n④ 국채전문 유통시장에서는 국고채권(외평채 포함) 뿐만 아니라 통화안정증권도 거래된다.",
