        "sourceText": "★★☆\n33. 여러가지 채권에 대한 설명이다. 옳지 않은 것은?\n① 수의상환청구채권의 수의상환청구권은 금리가 상승할수록 행사가능성이 커진다.\n② 교환사채의 교환시 발행사가 보유한 자산(주식)과 부채(교환사채)가 동시에 감소하는\n특징을 가진다.\n③ 투자자가 전환사채의 전환권 행사 시 추가 자금이 필요하지 않다.\n④ SPC에 대한 외부 신용보강을 하여도 원래 기초자산의 신용등급보다 높을 수는 없다.",
