        "explanation": "해설: 틀린 것은 ‘가, 다’이다.\n• 가: ‘금융소득종합과세 비대상자 요건’은 직전연도 기준이 아니라 ‘직전 3개년도 중 1회 이상 금융소득종합과세 대상이 아닐 것’으로 한다.\n• 다: 모델포트폴리오 중 하나를 선택하여 투자하는 방식은 일임형 ISA이다.\n※개인종합자산관리계좌(ISA) 내용정리\n(1) ISA의 가입유형은 ‘신탁형, 일임형, 중개형’의 세가지이며, 중복가입이 불가하므로 이 중에서 하나를 선택해서 가입할 수 있다.\n• 금융기관 통틀어 1인 1계좌만 가입이 가능함(금융기관 중복가입 불가).\n(2) 가입조건: ‘직전 3개년 중 1회 이상 금융소득종합과세 대상자가 아니어야 한다’는 기본 조건을 충족한 상태에서 유형별로 아래 요건을 충족하면 가입이 가능하다.\n• 일반형의 경우 만 19세이상은 소득이 없어도 가입이 가능하다(비교: 만 15세이상 19세 미만으로서 일반형에 가입하기 위해서는 근로소득이 있어야 함).\n• 서민형과 농어민형의 소득요건은 총급여 5,000만원 이하 또는 종합소득 3,800만원 이하인데, 동 소득요건을 초과할 경우 일반형이 된다.\n(3) 서민형과 농어민형의 경우, 통산순이익 400만원까지 비과세이며 400만원 초과분은 9.9%(지방세 포함) 분리과세한다.\n• 일반형의 경우 통산 순이익 200만원까지 비과세, 200만원 초과분은 9.9%로 분리과세한다.\n(4) 편입가능상품\n• 중개형ISA는 유일하게 국내상장주식을 편입할 수 있으나, 예금은 편입할 수 없다.\n(5) 운용 유형: 신탁형, 중개형, 일임형\n㉠ 신탁형, 중개형: 투자자가 편입상품을 직접 선택함(가입자의 지시가 없으면 다른 상품으로 교체불가).\n㉡ 일임형: 여러 개의 모델 포트폴리오 중에서 가입자 성향에 맞는 것을 선택해서 운용.",
        "sourceText": "★★★\n36. ISA(개인종합자산관리계좌)에 대한 설명이다. 틀린 것으로 연결한 것은?\n가. 일반형의 경우 금융소득종합과세 대상자가 아닐 경우 소득이 없어도 가입이 가능한데,\n이때 금융소득종합과세 대상자 여부의 판단은 직전 연도를 기준으로 한다.\n나. ISA의 의무가입기간은 3년이며 의무가입기간이 지나면 비과세 등의 세제혜택을 받을 수\n있는데, 서민형의 경우 통산순이익 기준 400만원까지 비과세 혜택을 받으며 400만 원을\n초과하는 통산순이익은 분리과세율(지방세 포함 9.9%)이 적용된다.\n다. 금융회사가 가입자의 위험성향과 자금운용목표를 고려하여 제시하는 모델포트폴리오 중\n하나를 선택하여 투자하는 방식은 중개형 ISA이다.\n① 가, 나\n② 나, 다\n③ 가, 다\n④ 가, 나, 다",
