        "explanation": "해설: 옳은 내용은 ④번이다\n※해설\n① 연금저축보험으로 판매하는 것이 일반적이지만 금융투자회사(증권사, 자산운용사)에서 ‘연금저축펀드’의 형태로 판매하기도 한다.\n② 연금계좌 전체 기준 연간 납입한도는 1,800만원이다.\n③ 세액공제를 받지 않은 원금에 대해서는 그 수익 분만 과세가 된다.\n④ 부득이한 사유(가입자의 사망, 해외이주, 파산선고, 개인회생 등)로 연금 외 수령을 할 경우 저율(3.3%~5.5%)의 분리과세가 적용된다(따라서 종합과세가 되지 않으므로 옳은 지문).\n※연금저축상품에 대한 과세\n(1) 연금수령한도 내 수령시에는 연령 별로 저율의 분리과세가 적용된다.\n→연금을 늦게 수령할수록 분리과세율이 낮아진다(나이는 만 나이 기준)\n(2) 연금 외 수령(연금수령한도를 초과하는 수령)시에는 고율(16.5%)의 분리과세가 적용되며, 연금수령액이 연간 1,500만원을 초과할 경우는 고율분리과세와 종합과세를 선택할 수 있다.\n• 단, 부득이한 사유(가입자의 사망, 해외이주, 파산선고 등)로 연금 외 수령을 하는 경우는 저율의 분리과세가 적용된다.\n(3) 연금소득세의 과세대상은 ‘세액공제를 받은 원금부분(ⓐ)과 그 수익분(ⓑ) 그리고 세액공제를 받지 않은 원금에 대한 수익 분(ⓒ)’의 3가지 부분으로 구성된다.\n• ③번 지문은 ‘세액공제 여부와 관계없이’ 그 원금에 대해서 과세한다고 하였으므로 틀린 내용이다.\n• 연금저축가입자에게는 세액공제 혜택이 주어지며 연금수령시에는 세액공제 받고 저축한 원금과 운용수익에 대해 연금소득세가 부과된다.",
        "sourceText": "★★☆\n37. 연금저축상품(세제적격 상품)에 대한 설명이다. 옳은 것은?\n① 자산운용사에서는 판매를 할 수 없다.\n② 연금계좌상품(연금저축계좌, 퇴직연금계좌, IRP계좌 포함)의 연간 납입한도는\n1,200만원이다.\n③ 연금저축 납입시 세액공제 혜택이 주어지며, 연금수령시에는 세액공제 여부와 관계없이\n그 원금과 수익분에 대해서 연금소득세가 부과된다.\n④ 가입자가 해외이주를 사유로 연금 외 수령을 할 경우 종합과세 대상에서 제외한다.",
