        "explanation": "해설: ‘내재가치>0’ → 돈이 되는(수익이 되는) 영역 → 내가격(In the money)\n※ELW의 가격구조\n(1) ELW가격=내재가치(행사가치)+시간가치\n[예] 기초자산가격이 10,000원, 행사가격이 8,000원인 콜ELW가격이 2,500원일 경우\n→㉠ 콜ELW의 내재가치=기초자산가격-행사가격=10,000원-8,000원=2,000원\n㉡ 2,500원=2,000원+시간가치*주1, 따라서 시간가치=500원\n*주1: 시간가치는 ELW의 만기 중에 기초자산가격의 변동으로 인하여 내재가치가 더 좋아질 가능성을 가격으로 반영한 것이다. 따라서 ELW의 시간가치는 만기가 많이 남아있을수록 기초자산의 변동성이 큰 상태일수록 커지게 된다.\n(2) 내가격/등가격/외가격: 내재가치가 양(+)인 상태를 ‘내가격(In the money)’이라 하고, 내재가치가 제로(0)인 상태를 ‘등가격(At the money)’이라 하고, 내재가치가 음(-)인 상태를 ‘외가격(Out of the money)’이라 한다.\n[예] 콜ELW의 내재가치는 ‘기초자산가격>행사가격’인 상태를 말하는데, 위 예시로 볼 때 ‘10,000원>8,000원=(+)2,000원’의 상태이므로 즉 내재가치가 양(+)이므로 이 콜ELW는 내가격 상태(‘돈이 되는 상태’)에 있다.\n※ ELW는 내재가치가 있는지 여부, 즉 돈이 되는 영역이 있는지 여부에 따라 내가격, 등가격, 외가격 ELW로 구분. 내재가치가 0보다 커서 현재 권리행사 가능구간으로 돈이 되는 영역에 있는 경우를 내가격이라 하고, 행사가격과 기초자산가격이 동일한 경우를 등가격, 내재가치가 0보다 작아서 현재 권리행사 포기가능 구간으로 돈이 되지 않는 영역에 있는 경우를 외가격이라 함. 최소이익의 보장은 없다. 대신 한정된 손실위험이다. 예를 들어 풋 ELW는 주식 및 주가지수 등의 기초자산의 하락이 예상될 때 매수한 것으로 최대 (손실)은 ELW의 (매수가격)으로 제한된다. 따라서 원금초과손실이 발생하지 않는다.",
        "sourceText": "★★★\n39. 주식워런트증권(ELW)의 가격구조와 관련하여, 보기에 대한 설명으로 틀린 것은?\n주식워런트증권 가격=내재가치(행사가치)+시간가치\n⑤ 행사가치는 권리를 행사함으로써 얻을 수 있는 이익으로 내재가치라고 할 수 있으며,\n콜워런트의 행사가치(내재가치)는 ‘기초자산가격-권리행사가격’이다.\n⑥ 시간가치는 만기까지의 잔존기간 동안 기초자산의 변동성 등에 따라 얻게 될 기대가치에\n해당한다.\n⑦ 내재가치가 0보다 커서 현재 권리행사 가능 구간으로서 돈이 되는 영역을 외가격이라\n한다.\n⑧ 콜워런트와 풋워런트 모두 만기에 근접할수록 시간가치는 감소하여 0(제로)에 수렴한다.",
