        "sourceText": "★★☆\n68. 투자자예탁금의 별도예치제도에 대한 설명이다. 틀린 항목으로 연결한 것은?\n가. ‘투자매매업자 또는 투자중개업자(예탁을 하는 예치 금융투자업자)’가 ‘증권금융회사\n또는 신탁업자(예탁을 받는 예치기관)’에게 투자자예탁금을 예치 또는 신탁하는\n경우에는, 그 투자자예탁금이 투자자의 재산임을 명시해야 한다.\n나. 겸영금융투자업자는 증권금융회사에 예치하지 않고 신탁업자에게 신탁할 수 있는데,\n겸영금융투자업자로서 은행과 보험회사 등이 자신이 신탁업자로서 투자자예탁금을\n보관하는 것은 금지된다.\n다. 예치 금융투자업자가 다른 회사에 흡수합병 되거나 금융투자업의 전부 또는 일부를\n양도하는 경우에는, 예치기관에 예치한 투자자예탁금을 인출하여 투자자에게 우선\n지급해야 한다.\n① 가, 나\n② 나, 다\n③ 가, 다\n④ 가, 나, 다",
