        "difficulty": 1,
        "question": "금융소비자보호법상 광고규제에 대한 설명으로 옳지 않은 것은?",
        "options": [
          "광고의 대상은 금융상품 뿐만 아니라 제공하는 각종 서비스도 포함한다.",
          "금융지주회사, 금융협회와 집합투자업자도 광고의 주체가 될 수 있다.",
          "광고주체가 금융상품 등에 대한 광고를 하는 경우 준법감시인의 심의를 받아야 한다.",
          "투자성 상품의 경우 금융상품판매대리·중개업자의 광고는 금융투자협회가 심사한다."
        ],
        "correctAnswer": 4,
        "answerNote": null,
        "explanation": "투자성 상품의 경우 금융상품판매대리·중개업자는 자본시장법상 투자권유대행인에 해당하는데 이들은 금융상품직접판매업자에 1사 전속으로 소속되어 활동하는 개인이므로 별다른 투자광고를 할 필요성이 없다. 따라서 금융상품판매대리·중개업자는 금융상품 뿐만 아니라 금융상품판매업자등의 업무에 관한 광고행위를 수행할 수 없으므로 당연히 협회도 심사하지 아니한다.\n※금소법 시행령 제17조(광고의 주체)\n1. 금융상품판매업자등을 자회사 또는 손자회사로 하는 금융지주회사\n2. 「자본시장과 금융투자업에 관한 법률」에 따른 증권의 발행인 또는 매출인(해당 증권에 관한 광고를 하는 경우로 한정한다)\n3. 집합투자업자\n4. 금융협회\n※ 광고에 포함하여야 할 사항(투자성 상품의 경우)\n1) 금융상품의 명칭, 수수료\n2) 투자에 따른 위험(원금손실발생 가능성, 원금손실에 대한 소비자의 책임)\n3) 과거 운용실적을 포함하여 광고를 하는 경우에는 그 운용실적이 미래의 수익률을 보장하는 것이 아니라는 사항",
        "sourceText": "★☆☆\n80. 금융소비자보호법상 광고규제에 대한 설명으로 옳지 않은 것은?\n① 광고의 대상은 금융상품 뿐만 아니라 제공하는 각종 서비스도 포함한다.\n② 금융지주회사, 금융협회와 집합투자업자도 광고의 주체가 될 수 있다.\n③ 광고주체가 금융상품 등에 대한 광고를 하는 경우 준법감시인의 심의를 받아야 한다.\n④ 투자성 상품의 경우 금융상품판매대리·중개업자의 광고는 금융투자협회가 심사한다.",
