        "correctAnswer": 4,
        "answerNote": null,
        "explanation": "거래소가 투자경고종목, 투자위험종목 또는 관리종목으로 지정한 증권은 신규의 신용거래를 할 수 없다. 투자주의종목의 지정(< 지정사유: 소수계좌 거래집중종목으로 뇌동매매 방지 목적)은 지정예고없이 1일간 지정되며 익일 자동해제되므로 신용거래가능하다.\n자본시장법 상 신용공여에 대한 규제로서 (→즉 금융투자업자가 임의로 정할 수 없음에 유의! 출제지문임), 투자매매업자 또는 중개업자는 투자자의 신용상태 및 종목별 거래상황 등을 고려하여 신용공여금액의 (140%) 이상에 상당하는 담보를 징구하여야 한다. 다만 매도되었거나 환매청구된 예탁증권을 담보로 하여 매도금액 또는 환매금액 한도내에서 융자를 하는 경우는 그러하지 아니하다.\n※금융투자업규정 제4-25조(담보비율 등)\n① 투자매매업자 또는 투자중개업자는 투자자의 신용상태 및 종목별 거래상황 등을 고려하여 신용공여금액의 100분의 140 이상에 상당하는 담보를 징구하여야 한다. 다만 매도되었거나 환매청구된 예탁증권을 담보로 하여 매도금액 또는 환매금액 한도 내에서 융자를 하는 경우에는 그러하지 아니하다.\n③ 투자매매업자 또는 투자중개업자는 신용공여금액에 대한 담보 평가금액의 비율이 투자매매업자 또는 투자중개업자가 정한 일정비율(“담보유지비율”이라 한다)에 미달하는 때에는 지체 없이 투자자에게 추가담보의 납부를 요구하여야 한다. 다만, 투자자와 사전에 합의한 경우에는 담보의 추가납부를 요구하지 아니하고 투자자의 계좌에 담보로 제공하지 아니한 현금 또는 증권을 추가담보로 징구할 수 있다",
        "sourceText": "★★☆\n84. 투자매매업자 및 투자중개업자의 신용공여에 대한 설명 중 옳지 못한 것은?\n① 투자매매업자 또는 투자중개업자는 투자자의 신용상태 및 종목별 거래상황 등을 고려하여\n신용공여금액의 100분의 140 이상에 상당하는 담보를 징구하여야 한다. 다만\n매도되었거나 환매청구된 예탁증권을 담보로 하여 매도금액 또는 환매금액 한도 내에서\n융자를 하는 경우에는 그러하지 아니하다.\n② 투자매매업자 또는 투자중개업자의 총 신용공여 규모는 자기자본의 범위 이내로 하되,\n신용공여 종류별로 투자매매업자 또는 투자중개업자의 구체적인 한도 및 계산방식은\n금융위원회 위원장이 따로 결정할 수 있다.\n③ 상장채권 및 공모파생결합증권(주가연계증권에 한함)의 담보평가는 2 이상의\n채권평가회사가 제공하는 가격정보를 기초로 투자매매업자 또는 투자중개업자가 산정한\n가격으로 한다.\n④ 거래소가 투자주의종목, 투자경고종목, 투자위험종목 또는 관리종목으로 지정한 증권은\n신규의 신용거래를 할 수 없다.",
