        "sourceText": "★☆☆\n85. 금융 분쟁에 관한 설명으로 가장 거리가 먼 것은?\n① 금융투자 관련 금융 분쟁은 주로 자본시장법령 등에서 부여하는 금융투자업자에게\n부여하는 의무 이행 여부가 쟁점이 된다.\n② 금융투자업 영위과정에서 거래관계가 수반되는 권리의무에 대한 상반된 주장이\n분쟁이라는 형태로 도출된다.\n③ 비록 금융업무 관련이라도 금융관련기관이 금융관련기관을 상대로 제기하는 분쟁은 금융\n분쟁에 해당하지 않는다.\n④ 금융수요자 등이 금융업무 등과 관련하여 이해관계 등이 발생함에 따라 금융관련기관을\n상대로 제기하는 분쟁이 금융 분쟁이다",
