        "explanation": "모두 금지대상이다\n※ 금지사항 추가\n• 재산상 이익이 사회적 상규에 반하거나 거래상대방의 공정한 업무수행을 저해하는 경우\n• 재산상 이익의 수수가 위법이나 부당행위의 은닉 또는 그 대가를 목적으로 하는 경우\n• 운용을 업무로 하는 자에게 금전, 상품권, 금융투자상품을 제공하는 경우(단, 그 사용범위가 공연이나 운동경기 등 문화활동에 한정된 상품권은 허용된다)\n※협회의 영업 및 업무에 관한 규정 (2-63조)\n② 다음 각 호의 어느 하나에 해당하는 경우에는 재산상 이익으로 보지 아니한다.\n1. 금융투자상품에 대한 가치분석·매매정보 또는 주문의 집행 등을 위하여 자체적으로 개발한 소프트웨어 및 해당 소프트웨어의 활용에 불가피한 컴퓨터 등 전산기기\n2. 금융투자회사가 자체적으로 작성한 조사분석자료\n3. 경제적 가치가 3만원 이하인 물품·식사·신유형상품권(공정거래위원회의 신유형 상품권 표준약관에 따른 물품 제공형 신유형 상품권을 말한다)·거래실적에 연동되어 거래상대방에게 차별없이 지급되는 포인트·마일리지\n4. 20만원 이하의 경조비 및 조화·화환\n5. 국내에서 불특정 다수를 대상으로 하여 개최되는 세미나 또는 설명회로서 1인당 재산상 이익의 제공금액을 산정하기 곤란한 경우 그 비용. 이 경우 대표이사 또는 준법감시인은 그 비용의 적정성 등을 사전에 확인하여야 한다.",
        "sourceText": "★★☆\n86. 다음 중 부당한 재산상이익의 제공 및 수령의 금지대상을 모두 묶은 것은?\n㉠ 경제적 가치가 일반인이 통상적으로 이해하는 수준을 초과하는 경우\n㉡ 거래상대방만 참석한 여가 및 오락활동에 수반되는 비용을 제공하는 경우\n㉢ 파생상품과 관련하여 추첨 기타 우연성을 이용한 방법으로 선정된 일반투자자에게 1회\n당 300만원을 초과하는 금전 등을 지급하는 경우\n㉣ 집합투자증권 판매회사의 변경을 권유하면서 백화점상품권을 제공하는 경우\n① ㉠, ㉡, ㉢\n② ㉠, ㉢, ㉣\n③ ㉡, ㉢, ㉣\n④ ㉠, ㉡, ㉢, ㉣",
