        "correctAnswer": 3,
        "answerNote": null,
        "explanation": "7영업일 내로 심의위원회를 소집하고 심의해야 한다.\n→배타적 사용권에 대한 침해발생 → 침해배제신청(to 협회) → 신청일로부터 7영업일 이내에 심의 위원장은 침해배제 신청 접수일로부터 7영업일 이내에 심의위원회를 소집하여 배타적 사용권 침해배제 신청에 대하여 심의하여야 한다.\n※ 신상품 보호(협회의 영업 및 업무에 관한 규정 (2-85조))\n1. “신상품”이란 금융투자상품 또는 이에 준하는 서비스로서 다음 각 목의 어느 하나에 해당하는 것을 말한다. 다만, 국내외에서 이미 공지되었거나 판매된 적이 없어야 한다.\n가. 새로운 비즈니스 모델을 적용한 상품 또는 서비스\n나. 금융공학 등 신금융기법을 이용하여 개발한 상품 또는 서비스\n다. 기존의 상품 또는 서비스와 구별되는 독창성이 있는 상품 또는 서비스\n2. “배타적 사용권”이란 신상품을 개발한 금융투자회사가 일정기간 동안 독점적으로 신상품을 판매할 수 있는 권리를 말한다.\n3. “신청회사”란 협회에 배타적 사용권 부여를 위한 심의를 신청한 금융투자회사를 말한다.",
        "sourceText": "★★☆\n87. 신상품 보호에 관한 협회규정을 설명한 것이다. 가장 거리가 먼 것은?\n① 신상품이란 새로운 비즈니스 모델을 적용한 금융투자상품 또는 이에 준하는 서비스 등을\n말하는데, 단 국내외에서 이미 공지되었거나 판매된 적이 없어야 한다.\n② 배타적 사용권이란 신상품을 개발한 금융투자회사가 일정기간 동안 독점적으로 신상품을\n판매할 수 있는 권리를 말한다.\n③ 배타적 사용권에 대한 직접적인 피해가 발생하고 금융투자회사가 침해배제신청을 한\n경우, 협회심의위원회 위원장은 침해배제 신청접수일로부터 10영업일 이내에\n심의위원회를 소집하고 심의해야 한다.\n④ 침해배제 신청이 이유가 있다고 결정된 경우 심의위원회는 지체 없이 침해회사에 대해\n침해의 정지를 명할 수 있다.",
