        "correctAnswer": 1,
        "answerNote": null,
        "explanation": "ⓒ 금융투자분석사는 자신의 금융투자상품 매매내역을 매월 회사에 보고하면 된다.\nⓓ 금융투자분석사는 자신이 담당하는 업종이 아닐 경우 매매는 할 수 있지만 공표일로부터 7일간 같은 방향으로 매매하여야 한다.\n※ 1)금융투자분석사의 매매거래 제한 :\n금융투자분석사는 자격을 취득하기 전에 취득한 금융투자상품을 처분하는 등 불가피한 예외적인 경우를 제외하고는 자신이 담당하는 업종에 속하는 법인이 발행한 주식, 주권관련사채권, 신주인수권이 표시된 것, 이러한 주식을 기초자산으로 하는 주식선물·주식옵션 및 주식워런트증권을 매매하여서는 안 된다.\n또한 금융투자분석사는 소속 금융투자회사에서 조사분석자료를 공표한 금융투자상품을 매매하는 경우에는 공표 후 24시간이 경과하여야 하며, 해당 금융투자상품의 공표일부터 7일 동안은 공표한 투자의견과 같은 방향으로 매매하여야한다.\n2) 금융투자분석사의 24시간 매매거래 제한의 예외 허용 :\n자본시장법은 조사분석자료 공표 후 24시간이 경과하기 전에 해당 회사가 자기계산으로 매매하는 행위 금지하나, 조사분석자료가 새로운 내용을 담고 있지 않은 경우 등에 대해서는 예외적으로 매매를 허용하고 있으므로, 협회 규정에서도 법상 고유계정(회사의 계산)에 적용되는 24시간 매매제한의 예외사항을 금융투자분석사의 자기계산 매매에 대해서도 허용하고 있다.",
        "sourceText": "★★☆\n88. 다음 중 조사분석자료에 대한 설명으로 옳은 것을 모두 고르시오.\nⓐ 금융투자회사는 자신이 발행한 주식을 기초자산으로 하는 주식워런트증권에 대해서는\n조사분석자료를 공표할 수 없다.\nⓑ 금융투자분석사가 기업금융업무 관련부서와 협의하고자 하는 경우 자료교환은 준법감\n시부서를 통하고 준법감시부서 직원의 입회하에 이루어져야 하며, 회의의 주요내용은\n서면으로 기록․유지되어야 한다.\nⓒ 금융투자분석사는 자신의 금융투자상품 매매내역을 분기별로 회사에 보고하여야 한다.\nⓓ 소속 회사에서 조사분석자료를 공표하는 경우 금융투자분석사는 자신이 분석을 담당하\n는 업종이 아니더라도 공표일부터 7일간은 해당 종목을 매매할 수 없다.\n① ⓐ,ⓑ\n② ⓐ,ⓓ\n③ ⓐ,ⓑ,ⓒ\n④ ⓐ,ⓑ,ⓓ",
