        "id": 97,
        "category": "4과목: 법규 및 세제",
        "difficulty": 3,
        "question": "아래의 정보 중 다음 연도에 종합소득 신고 및 납부 대상자는 모두 몇 명인가?",
        "options": [
          "4명",
          "3명",
          "2명",
          "1명"
        ],
        "correctAnswer": 4,
        "answerNote": null,
        "explanation": "1명이다. 라)의 근로소득과 사업소득만 있는 거주자는 확정신고 대상으로 종합소득 신고대상자이다.\n퇴직소득과 양도소득은 분류과세대상으로 타 소득과 합산하지 아니한다(합산이 되면 누진율이 적용되어 소득자에게 불리하므로 제외시킴). 사업소득은 기본적으로 종합소득신고 대상이지만 원천징수한 것은 제외된다(예를 들면, 주변에서 흔히 보는 전동카트로 영업하는 프레시 매니저는 근로소득자가 아닌 사업소득자이지만 소속회사에서 원천징수하므로 사업소득 신고를 별도로 하지 않는다)\n소득세는 납세자가 정부에 신고함으로써 과세표준과 세액이 확정된다. 따라서 소득금액과 세액을 계산하여 다음 연도 5월 1일부터 31일까지 주소지 관할세무서에 신고 및 납부하여야 한다.\n다만, 다음에 해당하는 거주자는 (종합소득)신고를 하지 않아도 된다.\n(1) 근로소득만 있는 거주자\n(2) 퇴직소득만 있는 거주자\n(3) 공적연금소득만 있는 자\n(4) 원천징수 연말정산하는 사업소득만 있는 자\n(4)의2. 원천징수되는 기타소득으로 종교인소득만 있는 자\n(5) 위 (1),(2) 소득만 있는 자\n(6) 위 (2),(3) 소득만이 있는 자\n(7) 위 (2),(4) 소득만이 있는 자\n(7)의2 위 (2),(4)의 소득만 있는 자\n(8) 분리과세이자·배당·연금·기타소득만 있는 자\n(9) 위 (1)~(7)의2에 해당하는 자로서 분리과세이자·배당·연금·기타소득이 있는 자",
        "sourceText": "★★★\n97. 아래의 정보 중 다음 연도에 종합소득 신고 및 납부 대상자는 모두 몇 명인가?\n가) 근로소득과 퇴직소득만 있는 거주자\n나) 원천징수 연말정산하는 사업소득만 있는 거주자\n다) 퇴직소득과 공적 연금소득만 있는 거주자\n라) 근로소득과 사업소득만 있는 거주자\n① 4명\n② 3명\n③ 2명\n④ 1명",
